/// Acts waiting for `apply`.
#[derive(Resource, Default)]
pub struct Queue(Vec<Act>);

/// Where the preferences and the control scheme are saved (next to the executable), and what changed since.
#[derive(Resource)]
pub struct Files {
    pub dir: PathBuf,
    settings: bool,
    controls: bool,
}

impl Files {
    fn settings_path(&self) -> PathBuf {
        self.dir.join("ppr-preferences.json")
    }
    fn controls_path(&self) -> PathBuf {
        self.dir.join("ppr-controls.json")
    }
}

/// The saved preferences over the game's config.json over the defaults.
pub fn load_settings(game: Option<&std::path::Path>) -> (Settings, Controls, Files) {
    let dir = std::env::current_exe().ok().and_then(|e| e.parent().map(PathBuf::from)).unwrap_or_default();
    let files = Files { dir, settings: false, controls: false };
    let mut settings = Settings::default();
    if let Some(text) = game.and_then(|g| std::fs::read_to_string(g.join("config.json")).ok()) {
        settings.load(&text);
    }
    if let Ok(text) = std::fs::read_to_string(files.settings_path()) {
        settings.load(&text);
    }
    let mut controls = Controls::default();
    if let Ok(text) = std::fs::read_to_string(files.controls_path()) {
        controls.load(&text);
    }
    (settings, controls, files)
}

/// ControlSchemeEditorBehaviour.ShouldReinitialise: set (by the ModAPI) to have the control scheme menu read the saved actions again.
#[derive(Resource, Default)]
pub struct ShouldReinitialise(pub bool);

/// EventSystem.currentSelectedGameObject, by the selected button's Act (the view is rebuilt, the button stays).
#[derive(Resource, Default)]
pub struct Selection(Option<Act>);

/// Each button's pointer state from before a rebuild: the game's buttons live on while the rewrite respawns them, so
/// the new ones take over the old ones' hover and colour tween (`carry_over`).
#[derive(Resource, Default)]
struct Carried(Vec<(Act, bool, Option<view::Tint>)>);

/// ControlSchemeEditorBehaviour.Update: when ShouldReinitialise is set, it is cleared, LoadInputSystem reads the saved actions over the defaults and
/// InitialiseControlScheme rebuilds the menu.
fn control_scheme_update(mut flag: ResMut<ShouldReinitialise>, mut controls: ResMut<Controls>, files: Res<Files>, mut ui: ResMut<Ui>) {
    if !flag.0 {
        return;
    }
    flag.0 = false;
    let mut loaded = Controls::default();
    if let Ok(text) = std::fs::read_to_string(files.controls_path()) {
        loaded.load(&text);
    }
    *controls = loaded;
    ui.dirty = true;
}

/// BackgroundItemLoader with the launch steps that exist (ModLoadStep, MapLoadStep, SteamContraptionLoadStep), and the MapRegistry its
/// MapLoadStep fills. It is the Menu scene's loader (level0): DontDestroyOnLoad keeps it, and so its Update, through the game
/// scene. Since 1.28.41 level1 has no loader of its own (the modcompilercoroutine object is gone), so nothing replaces it there.
struct Launch {
    loader: crate::game::background_loader::BackgroundItemLoader,
    registry: std::sync::Arc<std::sync::Mutex<Option<Result<Vec<data::MapEntry>, String>>>>,
    started: bool,
    /// The Menu scene's loading overlay TitleMesh and StateMesh texts.
    texts: Option<(String, String)>,
}

/// BackgroundItemLoader.Start once the install is known, then its Update every frame; a finished MapLoadStep shows in the map selection menu.
/// Global.OnDestroy's saves: NonSteamStatManager.SaveToFile("stats"), then ItemPersistence.Serialise; an exception from the first
/// leaves OnDestroy (Unity logs it with Debug.LogException) before the second.
fn global_on_destroy() {
    if let Err(exception) = crate::game::stats::save_to_file() {
        println!("exception	{exception}");
        return;
    }
    data::persistence_serialise();
}

/// Quitting during a game destroys the scene, so Global.OnDestroy runs (leaving it through the menu already did).
fn quit_saves(mut exit: MessageReader<AppExit>, play: Option<Res<Play>>) {
    if exit.read().count() > 0 && play.is_some() {
        global_on_destroy();
    }
}

fn launch(mut launch: NonSendMut<Launch>, mut ui: ResMut<Ui>) {
    // The last frame's end: a LoadingCoroutine at a WaitForEndOfFrame goes on.
    launch.loader.end_of_frame();
    if !launch.started && !ui.game.as_os_str().is_empty() {
        launch.started = true;
        // The Menu scene's BuiltInLoadSteps: ModLoadStep, MapLoadStep, SteamContraptionLoadStep.
        launch.loader.BuiltInLoadSteps.push(Box::new(data::ModLoadStep::new(ui.game.clone())));
        let step = data::MapLoadStep::new(ui.game.clone());
        launch.registry = step.registry.clone();
        launch.loader.BuiltInLoadSteps.push(Box::new(step));
        launch.loader.BuiltInLoadSteps.push(Box::new(data::SteamContraptionLoadStep::new()));
        // EarlyUpdate.ScriptRunDelayedStartupFrame: BackgroundItemLoader.Start.
        launch.loader.Start();
    }
    // BackgroundItemLoaderStatusBehaviour.Update (execution order 14, before BackgroundItemLoader's 20), while active:
    // TitleMesh.text = displayName ?? "", StateMesh.text = "<color=#ccc>" + displayState + "</color>".
    if let Some(name) = &launch.loader.status.shown {
        launch.texts = Some((name.clone(), format!("<color=#ccc>{}</color>", launch.loader.status.state)));
    }
    if launch.started {
        launch.loader.Update();
        // Update.ScriptRunDelayedDynamicFrameRate: a LoadingCoroutine continued after a step ended without yielding.
        launch.loader.after_update();
    }
    // The overlay is drawn while active (Show and Hide are SetActive), with the texts as last set (the scene's own before
    // the first Update).
    let launch = &mut *launch;
    let texts = launch.texts.get_or_insert_with(|| {
        const STATUS: &str = "Canvas/background loading item status";
        (scene::text("Menu", &format!("{STATUS}/title")), scene::text("Menu", &format!("{STATUS}/state")))
    });
    let shown = launch.loader.status.shown.as_ref().map(|_| (texts.0.clone(), texts.1.clone(), launch.loader.status.workshop));
    if shown != ui.loading_status {
        ui.loading_status = shown;
        ui.dirty = true;
    }
    let loaded = launch.registry.lock().unwrap().take();
    match loaded {
        Some(Ok(maps)) => {
            ui.maps = maps.into_iter().map(|m| MapRow { name: m.name, description: m.description }).collect();
            ui.dirty = true;
        }
        Some(Err(e)) => ui.error = Some(e),
        None => {}
    }
}

/// The maps list is MapRegistry, which BackgroundItemLoader's MapLoadStep fills.
pub fn new_ui(game: Option<PathBuf>, mode: Mode, map: Option<String>, item: Option<String>) -> Ui {
    let mut ui = Ui::new(Vec::new(), mode, map, item);
    ui.game = game.unwrap_or_default();
    ui
}

/// The whole UI, and the game's systems that run under it.
pub fn add(app: &mut App) {
    loading::add(app);
    app.insert_non_send(Launch { loader: crate::game::background_loader::BackgroundItemLoader::new(), registry: Default::default(), started: false, texts: None })
        .init_resource::<Queue>()
        .init_resource::<play::Textures>()
        .init_resource::<Fps>()
        .init_resource::<view::Flyouts>()
        .init_resource::<ShouldReinitialise>()
        .init_resource::<Selection>()
        .init_resource::<Carried>()
        .add_systems(Startup, setup)
        .add_systems(Update, (launch, start_at).chain())
        .add_systems(Last, (quit_saves, frame_limit))
        .add_systems(
            Update,
            (
                clicks,
                sliders,
                resize_catalog,
                colour_drag,
                hotkeys,
                typing,
                rebinding,
                (apply, menu_audio_update, logo_flash, (visual::menu_panels, visual::panels_time).chain().run_if(resource_exists::<Assets<crate::lights::Panels>>)).chain(),
                loading,
                late_catalog,
                scrolling,
                (rebuild, carry_over).chain(),
                live,
                notes_update,
                selection_box,
                (tints, eye_colour, events::pointer_events, control_scheme_update),
                (steam_warning, menu_disk_logger, achievement_toasts, spawnable_outline::spawnable_outline, scrollbar::scrollbars),
                save,
                window,
                (world_input, game_frame, (play::preload_gpu_textures, camera).chain(), play::limb_sprites, crate::limb_material::limb_materials, crate::wires::wires, crate::wires::tissue, crate::lines::lines, crate::energy_blur::energy_blurs, crate::tmp::draw::world_texts, crate::decals::decals, crate::particles::particles, play::object_sprites, (visual::panels, play::resprite, play::video_screens).chain(), (play::restyle, crate::delete_wire::delete_looks).chain(), (play::draw, crate::extras_view::draw, crate::extras_view::doorway, crate::mishap_view::draw, crate::mishap_phase_view::draw).chain(), spawnable_outline, play::spawnable_outline_sprites, crate::thumbnail::thumbnails, contraption_buttons).chain().run_if(resource_exists::<Play>),
            )
                .chain(),
        );
}

/// EyeImage's Image.color, which the eye's UiColorWave sets (game `eye`).
fn eye_colour(play: Option<Res<Play>>, mut eyes: Query<&mut ImageNode, With<view::EyeImage>>) {
    let Some(play) = play else { return };
    let [r, g, b, a] = play.game.eye.color;
    for mut i in &mut eyes {
        let c = Color::srgba(r, g, b, a);
        if i.color != c {
            i.color = c;
        }
    }
}

/// The Menu scene's UISoundBehaviour after its Start (Main = this) and the scene's AudioSources it plays on; a fresh
/// copy at each load of the scene, gone when the Main scene activates (`loading`). `listener` is the scene's
/// AudioListener's world position.
#[derive(Resource, Clone)]
pub struct MenuAudio {
    pub audio: crate::game::audio::Audio,
    pub ui_sound: crate::game::audio::UiSound,
    pub listener: [f32; 3],
    pub data_dir: PathBuf,
    /// The scene's Time.timeSinceLevelLoad (the loading overlay's shaders read it as _Time).
    pub level_time: f64,
}

/// PostLateUpdate.UpdateAudio in the Menu scene: the Doppler update (Time.deltaTime, the time scale being 1 there), then
/// its voices move on by Time.unscaledDeltaTime.
fn menu_audio_update(time: Res<Time<Real>>, menu: Option<ResMut<MenuAudio>>) {
    if let Some(mut m) = menu {
        let positions = m.audio.sources.iter().filter(|(_, s)| s.live() && (s.main.is_some() || !s.one_shots.is_empty())).map(|(&id, s)| (id, crate::game::audio::root_position(&s.chain))).collect();
        let listener = m.listener;
        m.audio.doppler_update(listener, time.delta_secs(), &positions);
        m.audio.update(time.delta_secs());
        m.level_time += time.delta_secs_f64();
    }
}

#[derive(Resource, Default)]
/// FramerateViewBehaviour: framesRenderedLastSecond, t and the Text ("000" until the first second).
struct Fps {
    frames: u32,
    time: f32,
    shown: Option<u32>,
}

/// Where the camera lights::setup made starts.
#[derive(Resource)]
struct StartAt(Vec3);

fn start_at(at: Option<Res<StartAt>>, mut camera: Single<(&mut Transform, &mut Projection), With<crate::lights::MainCamera>>, mut commands: Commands) {
    if let Some(at) = at {
        camera.0.translation = at.0;
        commands.remove_resource::<StartAt>();
    }
}

/// ContextMenuBehaviour.ClampToScreen on a window position (y down).
fn clamp_context(at: [f32; 2], screen: [f32; 2]) -> [f32; 2] {
    let c = crate::game::Game::context_clamp_to_screen([at[0], screen[1] - at[1]], screen);
    // ContextMenuBehaviour.ClampToScreen: transform.position after (Unity's screen pixels, y up).
    uifn("ContextMenuBehaviour.ClampToScreen", || format!("{},{}", c[0], c[1]));
    [c[0], screen[1] - c[1]]
}

/// ContextMenuBehaviour.Show at a window position: ClearDynamicButtons, the new dynamic buttons, ClampToScreen(screenPosition).
pub(super) fn show_context(ui: &mut Ui, at: [f32; 2], screen: [f32; 2], buttons: Vec<crate::game::menu::ShownButton>) {
    let before = ui.context_buttons.len();
    ui.context_buttons = buttons;
    let after = ui.context_buttons.len();
    uifn("ContextMenuBehaviour.ClearDynamicButtons", || format!("{before} {after}"));
    // CreateButton for each merged button (the last one's Identity and Description stay), then CreateDynamicButtons'
    // Separator: shown when there was any (Show hid it first).
    if let Some(b) = ui.context_buttons.last() {
        uifn("ContextMenuBehaviour.CreateButton", || format!("{} {}", b.Identity, ui_text(b.Description)));
    }
    uifn("ContextMenuBehaviour.CreateDynamicButtons", || format!("{after} {}", cs(after > 0)));
    ui.context = Some(clamp_context(at, screen));
    uifn("ContextMenuBehaviour.set_isOpen", || "True".into());
    uifn("ContextMenuBehaviour.Show", || format!("{} {after}", cs(ui.context.is_some())));
    ui.dirty = true;
}

/// ContextMenuBehaviour.Hide: closes the menu if open.
pub(super) fn hide_context(ui: &mut Ui) {
    let was = ui.context.is_some();
    if was {
        uifn("ContextMenuBehaviour.set_isOpen", || "False".into());
    }
    ui.context = None;
    let now = ui.context.is_some();
    uifn("ContextMenuBehaviour.Hide", || format!("{} {}", cs(was), cs(now)));
    ui.dirty = true;
}

/// The per-function checks (--ui-screens "uifn"): the state each checked UI step left, by the game method's name. Off
/// outside the harness, so play pays one atomic load per step.
pub(crate) static UIFN_ON: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
pub(crate) static UIFN: std::sync::Mutex<std::collections::BTreeMap<&'static str, String>> = std::sync::Mutex::new(std::collections::BTreeMap::new());

/// Set where the game runs EnvironmentSettingsController.RegenerateControls (the map's load, unpausing); the next view
/// build records it (view.rs environment_regenerated).
pub(super) static ENV_REGEN: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

pub(crate) fn uifn(method: &'static str, state: impl FnOnce() -> String) {
    if UIFN_ON.load(std::sync::atomic::Ordering::Relaxed) {
        UIFN.lock().unwrap().insert(method, state());
    }
}

/// A text as one uifn state: its line breaks and tabs written out (the recorder's UiText).
pub(super) fn ui_text(s: &str) -> String {
    s.replace('\r', "\\r").replace('\n', "\\n").replace('\t', "\\t")
}

/// DialogBox.Close of the text entry box (a button with ClosesDialogBox): the object goes at the frame's end.
fn entry_close(ui: &Ui) {
    if let Some(e) = &ui.entry {
        let n = ui.open_dialogbox_count();
        uifn("DialogBox.Close", || format!("{n} {}", ui_text(&e.title)));
    }
}

/// C#'s bool.ToString.
pub(super) fn cs(b: bool) -> &'static str {
    if b { "True" } else { "False" }
}

// ContextMenuBehaviour.Awake: Instance = this (Global reads `ui.context`); the RectTransform and CanvasScaler are layout
// ContextMenuBehaviour.Start: the menu starts hidden (`ui.context` is None)
// ContextMenuBehaviour.Hide: `ui.context = None` after a button's actions
// ContextMenuBehaviour.ClearDynamicButtons: `ui.context_buttons` is replaced by the next Show
// TextMeshProHyperlink.Awake: caches the TMP's textInfo.linkInfo, read only by TryGetLink, which no pointer event reaches (OnPointerClick)
// TextMeshProHyperlink.OnPointerEnter: the pointer events of OnPointerClick's texts
// TextMeshProHyperlink.OnPointerExit: the pointer events of OnPointerClick's texts
// TextMeshProHyperlink.TryGetLink: called by the pointer handlers only (OnPointerClick)
// TextMeshProHyperlink.OnPointerClick: its 6 objects (each scene's loading overlay's title and state) are TMP texts with m_RaycastTarget 0, which view::loading_status spawns Pickable::IGNORE: the raycast hits the overlay's Image, and a pointer event goes from there to its parents, not to these
// CatalogBehaviour.Start: LoadToyboxElementSize (resize_catalog), ItemPersistence.Deserialise, Populate, CreateCategoryButtons and CreateItemButtons (data::catalog, view::catalog), then SelectedCategory = the first category (`ui.category` starts at 0)
// CatalogBehaviour.OnDestroy: SpawnedGameObjects.Clear(); the list is only added to (ObjectState.CreateNew, CatalogBehaviour.Spawn) and removed from (PhysicalBehaviour.OnDestroy), never read, so the rewrite keeps none
// CatalogBehaviour.Populate: data::catalog reads Resources.LoadAll<SpawnableAsset>("SpawnableAssets"); spawnableByName and spawnableByPriorName are Game::get_spawnable's lookups
// CatalogBehaviour.get_Items: the read-only view of `items`, which is `ui.catalog.items`
// CatalogBehaviour.MoveNext: the rebuildUi coroutine of SetCategory, whose one effect is the item list's scroll back to the top (state.rs)
// CatalogBehaviour.System.Collections.IEnumerator.get_Current: the rebuildUi iterator's Current (a WaitForEndOfFrame)
// CatalogBehaviour.System.Collections.Generic.IEnumerator<System.Object>.get_Current: the same Current
// CatalogBehaviour.System.Collections.IEnumerator.Reset: the iterator's Reset (NotSupportedException in compiler-generated iterators)
// CatalogBehaviour.System.IDisposable.Dispose: the iterator's Dispose
// CatalogBehaviour.get_ExtraCategoryCount: Categories.Length - prevCategoryCount + ModdedCatalog.Count, 0 without mods; only
// CatalogDropdownBehaviour.Drop reads it (view.rs catalog, which stops past 9 categories)
// PageSwitchButtonBehaviour.Switch: MenuController.SetPage(pageName), the Act that pushes `pages` (state.rs)
// GameSettingsInitBehaviour.Start: Sync, whose body is empty
// MapPreviewLargeImageBehaviour.Update: presentation (an Image's sprite from the selected map's Preview or the Fallback; nothing reads it)
// NotificationControllerBehaviour.OnDestroy: Application.logMessageReceived -= LogMessageReceived; Game::log_message_received is called directly
// ConditionalTextBehaviour.Awake: TextMesh is set in the scene; GetProperty finds each of the seven properties (`context_property`), so no warning
// ContextMenuInteractableConditionalBehaviour.Awake: the button, tooltip and text are the static row view::hud spawns; GetProperty is `context_condition`'s match
// ContextMenuInteractableConditionalBehaviour.Update: `ui.context_enabled` is the flag from the property; view::hud sets interactable, the text colour and tooltip.enabled from it
// ToolControllerBehaviour.add_ToolChanged: ToolStatusView.Start subscribes; the status bar is drawn from `tool`, so the event is not needed
// ToolControllerBehaviour.remove_ToolChanged: ToolStatusView.OnDestroy unsubscribes; nothing is subscribed here
// CatalogBehaviour.remove_SelectionChanged: ToyStatusView.OnDestroy unsubscribes; the toy square is drawn from `item`
// SelectionController.add_SelectionChanged: no class of the game subscribes to it
// SelectionController.remove_SelectionChanged: no class of the game subscribes to it
// SelectionController.get_SelectedObjects: the read-only view of rawSelection, which the rewritten code reads directly
// TexturepackLoader.add_OnPackChange: no class of the game subscribes to it
// TexturepackLoader.remove_OnPackChange: no class of the game subscribes to it
// CameraControlBehaviour.add_PostRender: no class of the game subscribes to it
// CameraControlBehaviour.remove_PostRender: no class of the game subscribes to it
// CameraControlBehaviour.OnPostRender: invokes PostRender, which has no subscriber
// Toggle.Awake, Toggle.Update, TimeToggle.get_Visible and SlowmotionToggle.get_Visible: Main's two Toggles are the Check
// images of Canvas/On screen options/time and /slomo; that panel is inactive in the scene and no script, event or Find
// activates it, so Unity calls neither Awake nor Update and draws nothing of it; the rewrite leaves it out the same way.
// Toggle.Awake: image = GetComponent<Image>() (inactive panel, as above)
// Toggle.Update: image.enabled = Visible (inactive panel, as above)
// TimeToggle.get_Visible: Global.main.Paused (inactive panel, as above)
// SlowmotionToggle.get_Visible: Global.main.SlowMotion (inactive panel, as above)
// BackgroundItemLoaderStatusBehaviour.Awake: Instance and Hide: `ui.loading_status` starts None (launch)
// BackgroundItemLoaderStatusBehaviour.SetDisplayData: the name into Status.shown (BackgroundItemLoader.run_from); the thumbnail into Status.workshop: view::loading_status draws SteamWorkshopThumbnail for it, else DefaultThumbnailSprite (Show's null)
// BackgroundItemLoaderStatusBehaviour.Update: `launch` sets the TitleMesh and StateMesh texts that view::loading_status draws
// BackgroundItemLoaderStatusBehaviour.SetDisplayState: Status.state (MapLoadStep.resume)
// BackgroundItemLoaderStatusBehaviour.Show: SetDisplayData and SetActive(true): Status.shown is Some (BackgroundItemLoader.run_from)
// BackgroundItemLoaderStatusBehaviour.Hide: SetActive(false): Status.shown None (BackgroundItemLoader.run_from)
// CatalogDropdownBehaviour.Awake: presentation (reads the category row and item panel heights for the dropdown layout)
// CatalogDropdownBehaviour.Drop: presentation (shows the extra category rows and moves the item panel's top edge; no state read elsewhere)
// UserPreferenceLoader.Awake: UserPreferenceManager.Load is `load_settings`
// UserPreferenceLoader.OnDestroy: UserPreferenceManager.Save is `save`, which writes every change as it is made
// UISoundBehaviour.Refresh: RefreshButtons on Main when there is one: `clicks` gives every Button its Blip and `sliders` the SliderCallback
// TextMeshProControlReplacer.Start: presentation (substitutes InputSystem.GetDisplayText for control names in a label's text; only the label reads it)
// UIStatViewBehaviour.Start: state::stat_view_start (the GetFromSteam SetStat); the icon and StatName are view::page's Stats tiles
// UIStatViewBehaviour.OnEnable: Ui::stat_views_enable, at the scene load and each time the pause menu opens
// UIStatViewBehaviour.UpdateValue: state::stat_view_value, kept in `ui.stat_values` for the tiles
// RotateUI.Update: its 3 objects ("loading" under each loading overlay's mask) are inactive in the scenes (no script or field refers to them), so view::loading_status has no such child
// TextMeshInteractableSync.Update: presentation (TextMeshPro colour follows a Selectable's interactable flag)
// TextUpdaterBehaviour.Awake: textMesh is the button's label view::hud spawns from `label`
// LightTextureRenderer.OnRenderImage: never called: Main.unity's one LightTextureRenderer is disabled (m_Enabled 0) and no code enables it.
fn setup(mut commands: Commands, mut queue: ResMut<Queue>, mut ui: ResMut<Ui>, images: Option<ResMut<Assets<Image>>>, fonts: Option<ResMut<Assets<Font>>>) {
    commands.insert_resource(StartAt(Vec3::ZERO));
    let mut loaded = art::UiArt::default();
    if let (Some(mut images), Some(mut fonts), false) = (images, fonts, ui.game.as_os_str().is_empty()) {
        match art::load(&ui.game, &mut images, &mut fonts) {
            Ok(a) => loaded = a,
            Err(e) => eprintln!("UI art: {e}"),
        }
    }
    // The Menu scene's load (the scenes are read with the art).
    if ui.mode == Mode::Menu {
        commands.init_resource::<LogoFlashState>();
        ui.stat_views_load("Menu");
        if let Some(m) = &loaded.menu_audio {
            commands.insert_resource(m.clone());
        }
    }
    commands.insert_resource(loaded);
    // The hidden capture can open a page.
    match std::env::var("PPG_PAGE").as_deref() {
        Ok("maps") => queue.0.extend([Act::Nav(Page::Maps), Act::SelectMap(0)]),
        Ok("settings") => queue.0.push(Act::Nav(Page::Settings)),
        // A settings category by its index (settings:6, the extras' Mods).
        Ok(p) if p.starts_with("settings:") => queue.0.extend([Act::Nav(Page::Settings), Act::Tab(p[9..].parse().unwrap_or(0))]),
        Ok("mods") => queue.0.push(Act::Nav(Page::Mods)),
        Ok("environment") => queue.0.push(Act::Environment(true)),
        _ => {}
    }
}

/// VideoSettingsInitBehaviour.Sync: with VSync off, Application.targetFrameRate = Mathf.Max(12, FramerateLimit), so each
/// frame waits out the rest of its 1 / rate seconds; with VSync on the display paces it.
fn frame_limit(settings: Res<Settings>, mut last: Local<Option<std::time::Instant>>) {
    if !settings.flag("VSync") {
        let period = std::time::Duration::from_secs_f64(1.0 / settings.get("FramerateLimit").max(12.0) as f64);
        if let Some(e) = last.map(|t| t.elapsed()).filter(|e| *e < period) {
            std::thread::sleep(period - e);
        }
    }
    *last = Some(std::time::Instant::now());
}

/// The Menu scene's LogoFlashBehaviour: `t` and its object (None until Start).
#[derive(Resource, Default)]
pub struct LogoFlashState {
    t: f32,
    entity: Option<Entity>,
}

/// LogoFlashBehaviour.Start: Renderer.color = Gradient.Evaluate(0).
/// LogoFlashBehaviour.Update: unless Time.deltaTime > 1, Destroy the object once realtimeSinceStartup > 120 or t > Duration,
/// else t += unscaledDeltaTime and Renderer.color = Gradient.Evaluate(Clamp01(t / Duration)). A fresh one with each load of
/// the Menu scene; gone with the scene.
fn logo_flash(
    mut commands: Commands,
    time: Res<Time<Real>>,
    ui: Res<Ui>,
    art: Res<art::UiArt>,
    state: Option<ResMut<LogoFlashState>>,
    mut images: Query<&mut ImageNode, With<view::LogoFlash>>,
) {
    let Some(mut s) = state else { return };
    let gone = |commands: &mut Commands, s: &LogoFlashState| {
        if let Some(e) = s.entity {
            commands.entity(e).despawn();
        }
        commands.remove_resource::<LogoFlashState>();
    };
    if !matches!(ui.mode, Mode::Menu | Mode::Loading) {
        return gone(&mut commands, &s);
    }
    let gradient = |t: f32| {
        let v = scene::field("Menu", view::LOGO_FLASH, "LogoFlashBehaviour", "Gradient").expect("LogoFlashBehaviour.Gradient");
        let [r, g, b, a] = crate::game::visual::Gradient::read(v).expect("LogoFlashBehaviour.Gradient").evaluate(t);
        Color::srgba(r, g, b, a)
    };
    if s.entity.is_none() {
        match view::logo_flash(&mut commands, &art, gradient(0.0)) {
            Some(e) => s.entity = Some(e),
            None => return commands.remove_resource::<LogoFlashState>(),
        }
    }
    // Time.deltaTime: the real frame time capped at the Maximum Allowed Timestep (0.1), times the time scale (1 here).
    if time.delta_secs().min(0.1) > 1.0 {
        return;
    }
    let duration = scene::number("Menu", view::LOGO_FLASH, "LogoFlashBehaviour", "Duration");
    if time.elapsed_secs() > 120.0 || s.t > duration {
        return gone(&mut commands, &s);
    }
    s.t += time.delta_secs();
    let c = gradient((s.t / duration).clamp(0.0, 1.0));
    for mut i in &mut images {
        i.color = c;
    }
}

/// The pointer is over a UI node.
pub fn over_ui(hover: &HoverMap, nodes: &Query<(), With<Node>>) -> bool {
    hover.values().flat_map(|m| m.keys()).any(|&e| nodes.contains(e))
}

// ---------------------------------------------------------------- input

/// A button press and release on the same widget.
fn clicks(
    mouse: Res<ButtonInput<MouseButton>>,
    buttons: Query<(Entity, &Press, &Hovered)>,
    ui: Res<Ui>,
    mut queue: ResMut<Queue>,
    mut down: Local<Option<Act>>,
    mut selection: ResMut<Selection>,
    in_flyout: Query<&view::InFlyout>,
    mut flyouts: ResMut<view::Flyouts>,
) {
    let hovered = || buttons.iter().find(|(_, _, h)| h.get());
    let over = hovered().map(|(_, p, _)| p.0.clone());
    for button in [MouseButton::Left, MouseButton::Right, MouseButton::Middle] {
        if !mouse.just_pressed(button) {
            continue;
        }
        // StandaloneInputModule.ProcessMousePress (each button): DeselectIfSelectionChanged, then Selectable.OnPointerDown
        // (left only) selects the pressed button.
        if selection.0 != over {
            selection.0 = None;
        }
        if button == MouseButton::Left {
            selection.0 = over.clone();
        }
        // ItemButtonBehaviour.OnPointerDown (IPointerDownHandler: any button): SetItem, or the contraption's load.
        if let Some(act @ (Act::Item(_) | Act::Contraption(_))) = &over {
            queue.0.push(act.clone());
        }
    }
    if mouse.just_pressed(MouseButton::Left) {
        *down = over.clone();
    }
    // A click anywhere but on one of its buttons closes the context menu.
    let on_menu = hovered().is_some_and(|(_, p, _)| matches!(p.0, Act::Menu(_) | Act::MenuStatic(_)));
    if ui.context.is_some() && ((mouse.just_pressed(MouseButton::Left) && !on_menu) || mouse.just_pressed(MouseButton::Right)) {
        queue.0.push(Act::Escape);
    }
    if mouse.just_released(MouseButton::Left) {
        if let (Some(d), Some((e, press, _))) = (down.take(), hovered()) {
            if d == press.0 {
                // UISoundBehaviour.RefreshButtons gives Blip to the Buttons there are at the time (Resources.FindObjectsOfTypeAll,
                // inactive ones too), but not the piano keys (tagged NoSoundButton), and PlayBlip to the Toggles (the
                // environment checkboxes); the sliders' SliderCallback is in `sliders`. Every Button here has it when clicked:
                // the authored ones and what Awake or an order-0 Start makes (MenuController.Awake activates every page at the
                // scene load, so the settings, controls and resolution rows are made then) exist at UISoundBehaviour.Start
                // (execution order 1100), and what is made later is followed by a Refresh (CatalogBehaviour.CreateItemButtons,
                // ContextMenuBehaviour.Show, DialogBox's buttons, EnvironmentSettingsController.RegenerateControls,
                // MapSelectionMenuBehaviour.RegenerateView). Only ControlSchemeEditorBehaviour.ShouldReinitialise (ModAPI)
                // and ToolLibrary.OnCollectionChange (mods) make Buttons after it. The filter, hex code and number fields
                // are TMP_InputFields, not Buttons: no listener.
                match press.0 {
                    Act::PianoKey(_) | Act::Filter | Act::ModsFilter | Act::ColourHex | Act::EnvEdit(_) => {}
                    _ => queue.0.push(Act::UiSound(crate::game::audio::UiSoundKind::Blip)),
                }
                // The item buttons act on the press (above); their Button's onClick is only UISoundBehaviour's Blip.
                if !matches!(press.0, Act::Item(_) | Act::Contraption(_)) {
                    queue.0.push(press.0.clone());
                }
                // ToolBarGenerator.CreateButton: a variant's onClick also does childContainer.SetActive(false).
                if let Ok(view::InFlyout(parent)) = in_flyout.get(e) {
                    flyouts.clicked_in(parent);
                }
            }
        }
    }
}

/// Utils.getWorldSpaceBoundsBuffer's length (Utils' static setup: new Vector3[4]), the corners GetWorldCorners writes.
pub(crate) const GET_WORLD_SPACE_BOUNDS_BUFFER: usize = 4;

/// Utils.GetWorldSpaceBounds(rect) from GetWorldCorners: centre ((c0.x + c3.x) / 2, (c0.y + c1.y) / 2, 0) and size
/// (|c0.x - c3.x|, |c0.y - c1.y|, 0).
fn get_world_space_bounds(c: [[f32; 3]; GET_WORLD_SPACE_BOUNDS_BUFFER]) -> ([f32; 3], [f32; 3]) {
    ([(c[0][0] + c[3][0]) / 2.0, (c[0][1] + c[1][1]) / 2.0, 0.0], [(c[0][0] - c[3][0]).abs(), (c[0][1] - c[1][1]).abs(), 0.0])
}

/// ColorpickerDialogBehaviour.Update: dragging in the saturation/value box or the hue bar (a press there ends the hex
/// field's edit, as the click takes its focus). The handle stays inside the box (Bounds.ClosestPoint).
fn colour_drag(mouse: Res<ButtonInput<MouseButton>>, areas: Query<(&view::ColourArea, &Hovered, &RelativeCursorPosition)>, mut ui: ResMut<Ui>, mut drag: Local<Option<view::ColourArea>>) {
    if ui.colour.is_none() || !mouse.pressed(MouseButton::Left) {
        *drag = None;
        return;
    }
    if mouse.just_pressed(MouseButton::Left) {
        *drag = areas.iter().find(|(_, h, _)| h.get()).map(|(a, _, _)| *a);
        if let (Some(_), Some(b)) = (*drag, ui.colour.as_mut()) {
            b.end_edit();
        }
    }
    let Some(area) = *drag else { return };
    let Some(n) = areas.iter().find(|(a, _, _)| **a == area).and_then(|(_, _, r)| r.normalized) else { return };
    // The box's corners in the node's own normalised space (RectTransform.GetWorldCorners order: bottom left, top left,
    // top right, bottom right), Utils.GetWorldSpaceBounds of them, then Bounds.ClosestPoint(mouse).
    let (center, size) = get_world_space_bounds([[-0.5, -0.5, 0.0], [-0.5, 0.5, 0.0], [0.5, 0.5, 0.0], [0.5, -0.5, 0.0]]);
    let closest = |v: f32, c: f32, s: f32| v.clamp(c - s * 0.5, c + s * 0.5);
    let (x, y) = (closest(n.x, center[0], size[0]) + 0.5, closest(n.y, center[1], size[1]) + 0.5);
    let b = ui.colour.as_mut().unwrap();
    match area {
        view::ColourArea::SaturationValue => b.drag_sv(x, y),
        view::ColourArea::Hue => b.drag_hue(y),
    }
    ui.dirty = true;
}

// ResizableUIElementHandle.OnDeselect: StopResizing when another object is selected: a drag holds the mouse, so only the release ends it here
// ResizableUIElementHandle.OnDisable: StopResizing, the guard above
// CatalogBehaviour.SaveToyboxElementSize: ToyboxSizeOffset = ToResize.sizeDelta.x when more than 1 off (the end of resize_catalog)
/// ResizableUIElementHandle.OnPointerDown, ResizableUIElementHandle.Update, ResizableUIElementHandle.OnPointerUp and ResizableUIElementHandle.StopResizing on
/// the catalog (Axis Horizontal, SizeRange 483.6 to 1863.555, Step 153.3283). OnPointerDown: a left press on the handle begins the drag from the width and the mouse x.
/// ResizableUIElementHandle.Update: the mouse's travel through the CanvasScaler's scaleFactor, the camera's pixel width and the
/// 2688 reference width, snapped to the Step (Mathf.Round: ties to even), added to the initial width and clamped to SizeRange.
/// ResizableUIElementHandle.OnPointerUp: StopResizing; ResizableUIElementHandle.OnDisable and the Update guard (the catalog gone) do the same.
/// ResizableUIElementHandle.StopResizing: OnEndResize saves ToyboxSizeOffset when it is more than 1 off the width.
/// The handle's Graphic.color and Cursor.SetCursor follow the events, not the hover: `look` keeps the last colour set.
fn resize_catalog(
    mut commands: Commands,
    mouse: Res<ButtonInput<MouseButton>>,
    window: Single<(Entity, &Window), With<PrimaryWindow>>,
    art: Res<art::UiArt>,
    mut look: Local<Option<(bool, Color)>>,
    mut ui: ResMut<Ui>,
    mut settings: ResMut<Settings>,
    mut files: ResMut<Files>,
    mut handles: Query<(&Hovered, &mut BackgroundColor), With<view::ResizeHandle>>,
) {
    let (window_entity, window) = *window;
    let x = window.physical_cursor_position().map(|c| c.x);
    let over = handles.iter().any(|(h, _)| h.get());
    // ResizableUIElementHandle.Start: Graphic.color = Default (cam and canvasScaler are `window`'s numbers).
    let (was_over, mut color) = look.unwrap_or((false, view::handle_color("Default")));
    // None: leave the cursor; Some(false): Cursor.SetCursor(null); Some(true): Cursor.SetCursor(CursorSprite, (12, 5)).
    let mut cursor = None;
    if over && !was_over {
        // ResizableUIElementHandle.OnPointerEnter
        color = view::handle_color("Hover");
        cursor = Some(true);
    }
    if !over && was_over {
        // ResizableUIElementHandle.OnPointerExit: the handle is the selected object while it is dragged.
        let selected = ui.resizing.is_some();
        color = view::handle_color(if selected { "Active" } else { "Default" });
        cursor = Some(selected);
    }
    if mouse.just_pressed(MouseButton::Left) && over {
        if let Some(x) = x {
            ui.resizing = Some((view::catalog_width(&ui, &settings), x));
            color = view::handle_color("Active");
        }
    }
    if let Some((initial, from)) = ui.resizing {
        // ResizableUIElementHandle.Update's guard: ToResize and the handle must be active (no panels, or not the game: neither is drawn).
        let shown = !ui.hide_panels && ui.mode == Mode::Game;
        if mouse.pressed(MouseButton::Left) && shown {
            if let Some(x) = x {
                let pixels = window.physical_width() as f32;
                let scale = window.width() / 2688.0 * window.scale_factor();
                let (range, step) = view::handle_range();
                let travel = (x - from) * scale / pixels * 2688.0;
                let size = (initial + (travel / step).round_ties_even() * step).clamp(range[0], range[1]);
                if ui.toybox != Some(size) {
                    ui.toybox = Some(size);
                    ui.dirty = true;
                }
            }
        } else {
            ui.resizing = None;
            color = view::handle_color("Default");
            cursor = Some(false);
            let size = view::catalog_width(&ui, &settings);
            let i = Settings::index("ToyboxSizeOffset");
            if (settings.values[i] - size).abs() > 1.0 {
                settings.set(i, size);
                files.settings = true;
            }
            ui.dirty = true;
        }
    }
    *look = Some((over, color));
    match (cursor, &art.resize_cursor) {
        (Some(true), Some(image)) => {
            let image = bevy::window::CustomCursorImage { handle: image.clone(), hotspot: (12, 5), ..default() };
            commands.entity(window_entity).insert(bevy::window::CursorIcon::from(bevy::window::CustomCursor::Image(image)));
        }
        (Some(true), None) => unimplemented!("mod-only: the resize handle's CursorSprite did not load"),
        (Some(false), _) => {
            commands.entity(window_entity).insert(bevy::window::CursorIcon::default());
        }
        (None, _) => {}
    }
    for (_, mut bg) in &mut handles {
        if bg.0 != color {
            bg.0 = color;
        }
    }
}

/// SettingsGeneratorBehaviour.GenerateNumberSetting's slider.onValueChanged: the value snapped to the Step, whole for an int, set and applied
/// at once (the pointer-up apply finds nothing new). Dragging a settings slider.
fn sliders(
    mouse: Res<ButtonInput<MouseButton>>,
    tracks: Query<(&SliderOf, &Hovered, &RelativeCursorPosition)>,
    mut settings: ResMut<Settings>,
    mut files: ResMut<Files>,
    mut queue: ResMut<Queue>,
    mut drag: Local<Option<(usize, Vec2)>>,
) {
    let pressed = mouse.just_pressed(MouseButton::Left);
    if pressed {
        *drag = tracks.iter().find(|(_, h, _)| h.get()).and_then(|(s, _, r)| Some((s.0, r.normalized?)));
    }
    if !mouse.pressed(MouseButton::Left) {
        *drag = None;
    }
    let Some((i, last)) = *drag else { return };
    if let Some((_, _, rel)) = tracks.iter().find(|(s, _, _)| s.0 == i) {
        if let Some(n) = rel.normalized {
            // Slider.OnPointerDown and OnDrag (a pointer move): UpdateDrag sets the raw value, Lerp(min, max, t) (Round
            // for wholeNumbers); Set invokes onValueChanged when it differs from the stored (snapped) value, and
            // UISoundBehaviour.SliderCallback is one of its listeners.
            if pressed || n != last {
                drag.as_mut().unwrap().1 = n;
                if let Kind::Int { min, max, .. } | Kind::Float { min, max, .. } = SETTINGS[i].kind {
                    let t = crate::game::mathf::clamp01(n.x + 0.5);
                    let mut raw = crate::game::mathf::lerp(min, max, t);
                    if matches!(SETTINGS[i].kind, Kind::Int { .. }) {
                        raw = (raw as f64).round_ties_even() as f32; // Mathf.Round: Math.Round, to even
                    }
                    if raw != settings.values[i] {
                        queue.0.push(Act::UiSound(crate::game::audio::UiSoundKind::Slider));
                    }
                }
            }
            let before = settings.values[i];
            let mut next = settings.clone();
            next.set_fraction(i, n.x + 0.5);
            if next.values[i] != before {
                *settings = next;
                files.settings = true;
            }
        }
    }
}

/// The environment number field loses focus: onEndEdit (EnvironmentSettingsController.CreateNumberInput).
fn env_end_edit(ui: &mut Ui, unit: i32, play: Option<&mut Play>) {
    let Some(e) = ui.env_edit.take() else { return };
    if let Some(p) = play {
        p.game.environment_number_end_edit(e.row, &e.text, ENVIRONMENT[e.row].3, ENVIRONMENT[e.row].5, unit);
    }
    ui.dirty = true;
}

/// Keys typed into the catalog filter.
fn typing(mut keys: MessageReader<KeyboardInput>, mut ui: ResMut<Ui>, mut queue: ResMut<Queue>) {
    for key in keys.read() {
        if !key.state.is_pressed() {
            continue;
        }
        // The colour picker's hex code field, while it has focus: Enter ends the edit.
        if let Some(b) = ui.colour.as_mut() {
            if b.editing {
                match key.key_code {
                    KeyCode::Enter | KeyCode::NumpadEnter | KeyCode::Escape => b.end_edit(),
                    KeyCode::Backspace => {
                        b.hex.pop();
                    }
                    _ => b.hex.extend(key.text.iter().flat_map(|t| t.chars()).filter(|c| !c.is_control())),
                }
                ui.dirty = true;
            }
            continue;
        }
        // The entry box's input field (ContentType.DecimalNumber: digits, a leading minus and one point; Standard: any text).
        let u = &mut *ui;
        if let Some(e) = u.entry.as_mut() {
            // A selection is replaced by the next character or deleted by Backspace.
            let all = &mut u.entry_all;
            match key.key_code {
                KeyCode::Backspace => {
                    if std::mem::take(all) {
                        e.text.clear();
                    } else {
                        e.text.pop();
                    }
                }
                _ => {
                    for c in key.text.iter().flat_map(|t| t.chars()) {
                        let text = if *all { "" } else { e.text.as_str() };
                        if if e.number { c.is_ascii_digit() || (c == '-' && text.is_empty()) || (c == '.' && !text.contains('.')) } else { !c.is_control() } {
                            if std::mem::take(all) {
                                e.text.clear();
                            }
                            e.text.push(c);
                        }
                    }
                }
            }
            ui.dirty = true;
            continue;
        }
        // An environment number field (ContentType.DecimalNumber); Enter ends the edit, Escape restores the text first.
        if let Some(e) = u.env_edit.as_mut() {
            match key.key_code {
                KeyCode::Enter | KeyCode::NumpadEnter => queue.0.push(Act::EnvEnd),
                KeyCode::Escape => {
                    e.text = e.original.clone();
                    queue.0.push(Act::EnvEnd);
                }
                KeyCode::Backspace => {
                    if std::mem::take(&mut e.all) {
                        e.text.clear();
                    } else {
                        e.text.pop();
                    }
                }
                _ => {
                    for c in key.text.iter().flat_map(|t| t.chars()) {
                        let text = if e.all { "" } else { e.text.as_str() };
                        if c.is_ascii_digit() || (c == '-' && text.is_empty()) || (c == '.' && !text.contains('.')) {
                            if std::mem::take(&mut e.all) {
                                e.text.clear();
                            }
                            e.text.push(c);
                        }
                    }
                }
            }
            ui.dirty = true;
            continue;
        }
        // The Mods page filter: a TMP_InputField with characterLimit 256.
        if ui.mods_typing {
            match key.key_code {
                KeyCode::Escape | KeyCode::Enter => ui.mods_typing = false,
                KeyCode::Backspace => {
                    ui.mods_filter.pop();
                }
                _ => {
                    for c in key.text.iter().flat_map(|t| t.chars()).filter(|c| !c.is_control()) {
                        if ui.mods_filter.chars().count() < 256 {
                            ui.mods_filter.push(c);
                        }
                    }
                }
            }
            ui.dirty = true;
            continue;
        }
        if !ui.typing {
            continue;
        }
        match key.key_code {
            KeyCode::Escape | KeyCode::Enter => ui.typing = false,
            KeyCode::Backspace => {
                ui.filter.pop();
                ui.filter_applied = true;
            }
            _ => {
                for c in key.text.iter().flat_map(|t| t.chars()).filter(|c| !c.is_control()) {
                    ui.filter.push(c);
                    ui.filter_applied = true;
                }
            }
        }
        ui.dirty = true;
    }
}

/// A KeyCode name's value, which orders the KeyCode loops of TriggerEditorBehaviour.HasReceivedUserInput.
fn keycode_value(name: &str) -> i32 {
    crate::game::keycode::KEYCODES.iter().find(|(_, n)| *n == name).map_or(i32::MAX, |x| x.0)
}

/// What TriggerEditorBehaviour.WaitForUserInput keeps: Input.mousePosition at the start, the stage it is waiting at and its
/// copy of the InputAction's Key and SecondaryKey.
type Waiting = (Vec2, u8, String, String);

/// TriggerEditorBehaviour.StartWaiting, TriggerEditorBehaviour.WaitForUserInput and TriggerEditorBehaviour.HasReceivedUserInput: wait until no key
/// is held; then every frame SecondaryKey = the last held KeyCode (by value; None when none) and, once a KeyCode comes up,
/// Key = the first one that did; moving the mouse over 200 pixels restores Key (SecondaryKey keeps what the last poll set);
/// on a key, wait until no key is held again. SaveStateChanges stores the action and InputSystem.Save writes the file.
fn rebinding(
    keys: Res<ButtonInput<KeyCode>>,
    mouse: Res<ButtonInput<MouseButton>>,
    window: Single<&Window, With<PrimaryWindow>>,
    mut ui: ResMut<Ui>,
    mut controls: ResMut<Controls>,
    mut files: ResMut<Files>,
    mut state: Local<Option<Waiting>>,
) {
    let Some(i) = ui.rebinding else {
        *state = None;
        return;
    };
    let cursor = window.cursor_position().unwrap_or_default();
    let (start, stage, key, secondary) = state.get_or_insert_with(|| (cursor, 0, controls.binds[i].0.clone(), controls.binds[i].1.clone()));
    let any = keys.get_pressed().next().is_some() || mouse.get_pressed().next().is_some();
    let mut done = false;
    match *stage {
        0 => {
            if !any {
                *stage = 1;
            }
        }
        1 => {
            let mut held: Vec<String> = keys.get_pressed().map(|&k| Src::Key(k)).chain(mouse.get_pressed().map(|&b| Src::Mouse(b))).filter_map(keys::name).collect();
            held.sort_by_key(|n| keycode_value(n));
            *secondary = held.pop().unwrap_or_else(|| "None".into());
            let mut up: Vec<String> = keys.get_just_released().map(|&k| Src::Key(k)).chain(mouse.get_just_released().map(|&b| Src::Mouse(b))).filter_map(keys::name).collect();
            up.sort_by_key(|n| keycode_value(n));
            let received = !up.is_empty();
            if received {
                *key = up.swap_remove(0);
            }
            let state = format!("{} {key}", cs(received));
            uifn("TriggerEditorBehaviour.HasReceivedUserInput", || state);
            let moved = (cursor - *start).length() > 200.0;
            if received || moved {
                if moved {
                    *key = controls.binds[i].0.clone();
                    done = true;
                } else {
                    *stage = 2;
                }
            }
        }
        _ => done = !any,
    }
    if done {
        controls.set(i, key, secondary);
        ui.rebinding = None;
        uifn("TriggerEditorBehaviour.set_IsBeingEdited", || "False".into());
        ui.dirty = true;
        files.controls = true;
    }
}

// InputSystem.Held, InputSystem.Down and InputSystem.Up: the action's IsHeld, IsPressed and IsReleased (an id that is not an action is not asked)
// InputSystem.IsInUniverse: UniverseMatches against CurrentUniverse, which Global.Start sets to Game
// InputAction.get_IsInCurrentUniverse: InputSystem.IsInUniverse of the action's Universe
// InputSystem.Has: every id asked is an action of the table
// InputSystem.GetDisplayText: presentation (TextMeshProControlReplacer's label text)
// InputAction.GetDisplayText: presentation (Key and SecondaryKey as label text)
/// InputAction.IsHeld, InputAction.IsPressed and InputAction.IsReleased: the key bound to an action, as the game would test it (the
/// secondary key must be held for each, a release included).
pub fn eval(controls: &Controls, id: &str, inputs: &Inputs) -> crate::game::tool::Control {
    let (key, secondary) = controls.bind(id);
    // Global.Start: CurrentUniverse = Game; UniverseMatches(None) is false, All matches, else equal.
    if !matches!(ACTIONS[Controls::index(id)].universe, "All" | "Game") {
        return Default::default();
    }
    let Some(k) = keys::src(key) else { return Default::default() };
    let ok = keys::src(secondary).is_none_or(|s| inputs.held(s));
    crate::game::tool::Control { down: inputs.down(k) && ok, held: inputs.held(k) && ok, up: inputs.up(k) && ok }
}

/// The control scheme's UI and time actions.
fn hotkeys(
    keys: Res<ButtonInput<KeyCode>>,
    mouse: Res<ButtonInput<MouseButton>>,
    controls: Res<Controls>,
    mut ui: ResMut<Ui>,
    mut queue: ResMut<Queue>,
    play: Option<Res<Play>>,
) {
    let inputs = Inputs { keys: &keys, mouse: &mouse };
    // Global.Update: !TriggerEditorBehaviour.IsBeingEdited (read every frame) && !ActiveUiBlock
    uifn("TriggerEditorBehaviour.get_IsBeingEdited", || cs(ui.rebinding.is_some()).into());
    // EnvironmentSettingsController.Update runs every frame the window is open, the pause menu's too (the toybox close below).
    if ui.env_open {
        uifn("EnvironmentSettingsController.Update", || "True".into());
    }
    if ui.rebinding.is_some() || ui.typing || ui.env_edit.is_some() {
        return;
    }
    let pressed = |id: &str| eval(&controls, id, &inputs).down;
    let released = |id: &str| eval(&controls, id, &inputs).up;
    // "pause" in a game is Global.Update's (game/global.rs, through world_input). The UI keeps the main menu's Escape, the
    // pause menu's pages (InvokeOnEscape: Back, while the page is not Main, so Global leaves it) and closing the context menu.
    ui.pause_taken = false;
    if pressed(crate::il!(str "Global::Update" 0)) && (play.is_none() || ui.mode == Mode::Menu || ui.context.is_some() || (ui.mode == Mode::Pause && ui.pages.len() > 1)) {
        queue.0.push(Act::Escape);
        ui.pause_taken = play.is_some();
    }
    if ui.mode != Mode::Game {
        return;
    }
    // time, slowmo, toggleLimbStatus, toggleHoveringHighlights and the snapping keys are Global.Update's.
    // ToolWheelBehaviour.Update's toolPowerToggle (SetTab and the notification) runs on the game side (tool_wheel_update).
    // EnvironmentSettingsController.Update: the window closes when the toybox key comes up, unless the pause menu is open
    // (GetPausedMenu), any DialogBox is open (IsAnyDialogboxOpen) or a UI block is held (Global.ActiveUiBlock).
    let free = play.as_ref().is_none_or(|p| p.game.key_boxes.is_empty() && p.game.piano.is_none() && p.game.ActiveUiBlockers == 0);
    if ui.env_open {
        if ui.mode != Mode::Pause && ui.entry.is_none() && ui.colour.is_none() && ui.dialog.is_none() && free && eval(&controls, crate::il!(str "EnvironmentSettingsController::Update" 0), &inputs).up {
            ui.env_open = false;
            ui.dirty = true;
        }
        uifn("EnvironmentSettingsController.Update", || cs(ui.env_open).into());
    }
    // CatalogToggleBehaviour.UpdateUiVisibility: Canvas.enabled = Global.UiEnabled (`hide_ui`).
    // In Update "toggleUi" flips Global.UiEnabled first (Global.OnUiToggle's scene calls are not modelled), then "toybox" flips
    // ToggledOn only while the canvas is enabled and the environment settings are closed.
    // CatalogToggleBehaviour.Update reads InputSystem.Up for both keys.
    // CatalogToggleBehaviour.Update and ToolWheelBehaviour.Update both return while a DialogBox is open or a UI block is active.
    let blocked = ui.entry.is_some() || ui.colour.is_some() || play.as_ref().is_some_and(|p| p.game.global_active_ui_block());
    if released("toggleUi") && !blocked {
        ui.hide_ui = !ui.hide_ui;
        ui.dirty = true;
    }
    // "toybox" up flips CatalogToggleBehaviour.ToggledOn and ToolWheelBehaviour.Toggle's isOpen under the same tests, so one
    // flag (`hide_panels`) is both: the toolbar's localScale is 1.2 while open and zero (not drawn) while closed.
    if released(crate::il!(str "ToolWheelBehaviour::Update" 0)) && !ui.hide_ui && !ui.env_open && !blocked {
        ui.hide_panels = !ui.hide_panels;
        ui.dirty = true;
    }
    // CatalogToggleBehaviour.Update past its early return (no pause menu, dialog box or UI block): ToggledOn and ToToggle's
    // localScale.x (its Lerp at 0.7 a frame long arrived: drawn at 1 or 0).
    if ui.mode != Mode::Pause && play.as_ref().is_some_and(|p| !p.game.global_active_ui_block()) && !ui.is_any_dialogbox_open() {
        let on = !ui.hide_panels;
        uifn("CatalogToggleBehaviour.Update", || format!("{} {}", cs(on), if on { 1 } else { 0 }));
    }
}

/// Wheel over a scrolling list. `ui.scroll` and the list's ScrollPosition follow each other: a state change (CatalogBehaviour.SetCategory's
/// rebuildUi, a settings tab's SetCategory) moves the list, the wheel, the layout's clamp and a rebuild move the state.
fn scrolling(
    wheel: Res<AccumulatedMouseScroll>,
    mut lists: Query<(&Scroll, &Hovered, &mut ScrollPosition, &ComputedNode)>,
    mut ui: ResMut<Ui>,
    mut synced: Local<std::collections::HashMap<u8, f32>>,
) {
    for (&Scroll(id, sensitivity), hovered, mut pos, node) in &mut lists {
        if let Some(&want) = ui.scroll.get(&id) {
            if synced.get(&id) != Some(&want) && pos.y != want {
                pos.y = want;
            }
        }
        if hovered.get() && wheel.delta.y != 0.0 {
            // ScrollRect.OnScroll: content moves by scrollDelta * m_ScrollSensitivity (a line is one scrollDelta), clamped.
            let step = if wheel.unit == MouseScrollUnit::Line { sensitivity } else { 1.0 };
            let max = ((node.content_size().y - node.size().y) * node.inverse_scale_factor()).max(0.0);
            pos.y = (pos.y - wheel.delta.y * step).clamp(0.0, max);
        }
        if ui.scroll.get(&id) != Some(&pos.y) {
            ui.scroll.insert(id, pos.y);
        }
        synced.insert(id, pos.y);
    }
}

// ---------------------------------------------------------------- actions

fn apply(
    mut queue: ResMut<Queue>,
    mut ui: ResMut<Ui>,
    mut settings: ResMut<Settings>,
    mut controls: ResMut<Controls>,
    mut files: ResMut<Files>,
    time: Res<Time<Real>>,
    mut exit: MessageWriter<AppExit>,
    mut commands: Commands,
    mut play: Option<ResMut<Play>>,
    mut menu: Option<ResMut<MenuAudio>>,
    art: Res<art::UiArt>,
    // The Main scene's objects, destroyed when it unloads.
    sprites: Query<Entity, With<play::MainScene>>,
) {
    let now = time.elapsed_secs_f64();
    for act in std::mem::take(&mut queue.0) {
        // A lower box's button: that box comes to the top (the old top goes under it), then the button as on the top box.
        let act = match act {
            Act::DialogUnder(k, i) if k < ui.under.len() => {
                let d = ui.under.remove(k);
                ui.open_dialog(d);
                Act::DialogButton(i)
            }
            a => a,
        };
        // A TMP_InputField loses focus (onEndEdit) when anything else is clicked.
        if ui.env_edit.is_some() && !matches!(&act, Act::EnvEdit(i) if ui.env_edit.as_ref().is_some_and(|e| e.row == *i)) {
            env_end_edit(&mut ui, settings.get("TemperatureUnit") as i32, play.as_deref_mut());
        }
        match &act {
            Act::EnvToggle(i) => {
                if let Some(p) = play.as_deref_mut() {
                    if let Some(on) = p.game.environment_toggle_value(*i) {
                        p.game.environment_settings_set_value(crate::game::map::environment_value(*i, if on { 0.0 } else { 1.0 }));
                    }
                }
                ui.dirty = true;
            }
            Act::EnvEdit(i) => {
                if ui.env_edit.is_none() {
                    let unit = settings.get("TemperatureUnit") as i32;
                    let temperature = ENVIRONMENT[*i].5;
                    if let Some(text) = play.as_deref().and_then(|p| p.game.environment_number_text(*i, temperature, unit)) {
                        ui.env_edit = Some(state::EnvEdit { row: *i, original: text.clone(), text, all: true });
                    }
                }
                ui.dirty = true;
            }
            Act::EnvEnd => {}
            Act::LayerOffset(layer, up) => {
                if let Some(p) = play.as_deref_mut() {
                    if *layer {
                        p.game.layer_editor_raw_offset_layer(*up);
                    } else {
                        p.game.layer_editor_raw_offset_order(*up);
                    }
                }
                ui.dirty = true;
            }
            // ClearDebrisBehaviour.Clear / ClearLivingBehaviour.Clear / ClearButtonBehaviour.ClearEverything.
            Act::ClearMess | Act::ClearLiving | Act::ClearEverything if ui.mode == Mode::Game => {
                if let Some(p) = play.as_deref_mut() {
                    match act {
                        Act::ClearMess => p.game.clear_debris(),
                        Act::ClearEverything => p.game.clear_everything(),
                        _ => p.game.clear_living(),
                    }
                }
            }
            Act::Tool(_, ty) => {
                if let Some(p) = play.as_deref_mut() {
                    p.game.set_tool_by_type_name(ty);
                }
            }
            // toggle-visibility's Button.onClick: ToolWheelBehaviour.ToggleToolVisibility.
            Act::ToolVisibility => {
                if let Some(p) = play.as_deref_mut() {
                    if p.game.tool.is_some() {
                        p.game.tool_wheel_toggle_tool_visibility();
                    }
                }
            }
            // tab-tools / tab-powers Button.onClick: ToolWheelBehaviour.SetTab(0 / 1).
            Act::Powers(powers) => {
                if let Some(p) = play.as_deref_mut() {
                    if p.game.tool.is_some() {
                        p.game.tool_wheel_set_tab(*powers as i32);
                    }
                }
            }
            Act::LimbStatus => {
                if let Some(p) = play.as_deref_mut() {
                    p.game.toggle_limb_status();
                }
            }
            // DialogBox.get_EnteredText: the input field's text, `EntryBox::text`, read by the apply callback
            Act::EntryApply => {
                entry_close(&ui);
                if let (Some(p), Some(e)) = (play.as_deref_mut(), ui.entry.take()) {
                    if let Some(b) = p.game.entry.as_mut() {
                        b.text = e.text;
                    }
                    p.game.entry_apply();
                }
                ui.dirty = true;
            }
            Act::ColourApply => {
                if let (Some(p), Some(b)) = (play.as_deref_mut(), ui.colour.take()) {
                    p.game.colour = Some(b);
                    p.game.colour_apply();
                }
                ui.dirty = true;
            }
            // ColorpickerDialogBehaviour.Cancel: Close (the box and the UI blocker go), then OnCancel (no listener)
            Act::ColourCancel => {
                if let Some(p) = play.as_deref_mut() {
                    // ColorpickerDialogBehaviour.Close
                    if p.game.colour.take().is_some() {
                        p.game.global_remove_ui_blocker();
                        uifn("ColorpickerDialogBehaviour.Close", || "False".into());
                        uifn("ColorpickerDialogBehaviour.Cancel", || "False".into());
                    }
                }
                ui.colour = None;
                ui.dirty = true;
            }
            Act::ColourHex => {
                if let Some(b) = ui.colour.as_mut() {
                    b.editing = true;
                }
                ui.dirty = true;
            }
            Act::UiSound(kind) => {
                if let Some(p) = play.as_deref_mut() {
                    p.game.ui_sound(*kind);
                } else if let Some(m) = menu.as_deref_mut() {
                    // The Menu scene's Main, at Time.unscaledTime.
                    let MenuAudio { audio, ui_sound, .. } = m;
                    ui_sound.play(audio, now as f32, *kind);
                }
            }
            Act::PianoKey(_) | Act::PianoApply | Act::PianoCancel => {
                if let Some(p) = play.as_deref_mut() {
                    let g = &mut p.game;
                    match act {
                        // UiPianoKeyBehaviour's onClick: Source.PlayOneShot(BellClip.Clip), SelectedBellClip = BellClip.
                        Act::PianoKey(k) => {
                            if let Some((source, clip)) = g.piano_key_audio.get(k).cloned() {
                                let source = source.unwrap_or_else(|| crate::game::menu::throw("NullReferenceException: UiPianoKeyBehaviour.Source"));
                                g.audio.play_one_shot(source, clip.as_ref(), 1.0);
                            }
                            if let Some(pi) = g.piano.as_mut() {
                                pi.selected = crate::game::menu::PianoPick::Key(k);
                            }
                        }
                        Act::PianoApply => g.piano_apply(),
                        // PianoDialogBox.Hide: Cancel closes the dialog
                        // PianoDialogBox.Start: Instance = this, then Hide: the dialog starts hidden (`piano` is None)
                        _ => g.piano = None,
                    }
                }
                ui.dirty = true;
            }
            Act::LimbViewClose => {
                if let Some(p) = play.as_deref_mut() {
                    p.game.limb_view.active = false;
                }
                ui.dirty = true;
            }
            Act::KeyWait | Act::KeyApply | Act::KeyCancel => {
                if let Some(p) = play.as_deref_mut() {
                    let g = &mut p.game;
                    if let Act::KeyWait = act {
                        let mouse = g.input.screen.map(|s| s.mouse);
                        if let Some(b) = g.key_boxes.last_mut() {
                            if b.wait.is_none() {
                                b.wait = Some(crate::game::menu::KeyWait::new(b.key, mouse));
                            }
                        }
                    } else if let Some(b) = g.key_boxes.pop() {
                        // DialogBox.Close (ClosesDialogBox): the object goes at the frame's end.
                        let n = ui.open_dialogbox_count();
                        uifn("DialogBox.Close", || format!("{n} {}", ui_text(crate::il!(str "KeyTriggerBehaviour::<Start>b__12_0" 0))));
                        // setKeyFromDialog (UpdateDisplay is rendering).
                        if let Act::KeyApply = act {
                            g.key_triggers[b.trigger].KeyCode = b.key;
                            uifn("DialogBox.get_InputKey", || b.key.to_string());
                        }
                    }
                }
                ui.dirty = true;
            }
            // ExportGameDebugInfoBehaviour.Export.
            Act::DeleteContraption(i) => {
                if let (Some(p), Some(m)) = (play.as_deref_mut(), ui.catalog.items.get(*i).and_then(|it| it.local.clone())) {
                    p.game.contraption_delete_dialog(m);
                }
            }
            // PublishButtonBehaviour.Publish: no Steam, so an Error and the notification.
            Act::ItemPublish(_) => {
                if let Some(p) = play.as_deref_mut() {
                    p.game.ui_sound(crate::game::audio::UiSoundKind::Error);
                }
                ui.open_dialog(state::DialogView::notification(crate::game::mods::publish_button_publish()));
                ui.dirty = true;
            }
            Act::ExportDebugInfo => {
                ui.open_dialog(debug_info::export(&debug_info::system_info()));
                ui.dirty = true;
            }
            // DialogButton: the delegate, then DialogBox.Close when ClosesDialogBox.
            &Act::DialogButton(i) => {
                if let Some(d) = ui.dialog.clone() {
                    // Select anyway closes its box, then loads (the contraption's own box or notification may follow).
                    if let Some(DialogRun::SelectContraption(c)) = d.buttons[i].2 {
                        ui.close_dialog();
                        ui.load_selected_contraption(c, now);
                    } else {
                        if let Some(r) = &d.buttons[i].2 {
                            debug_info::run(r);
                            if let (DialogRun::Game(a), Some(p)) = (r, play.as_deref_mut()) {
                                p.game.contraption_dialog_action(a);
                            }
                        }
                        if d.buttons[i].1 {
                            ui.close_dialog();
                        }
                    }
                }
                ui.dirty = true;
            }
            Act::EntryCancel => {
                entry_close(&ui);
                if let Some(p) = play.as_deref_mut() {
                    p.game.entry = None;
                }
                ui.entry = None;
                ui.dirty = true;
            }
            // A static button: its action (which hides the menu itself).
            &Act::MenuStatic(k) => {
                if let (Some(p), Some(at)) = (play.as_deref_mut(), ui.context) {
                    let g = &mut p.game;
                    // Camera.main.ScreenToWorldPoint(transform.position): the menu's corner (window y runs down).
                    let world = match (g.input.screen, g.input.window) {
                        (Some(s), Some(w)) => s.to_world([at[0], w.size[1] - at[1]]),
                        _ => [0.0, 0.0],
                    };
                    if g.context_static_click(CONTEXT_MENU[k].0, world) {
                        hide_context(&mut ui);
                    }
                }
                ui.dirty = true;
            }
            // The button's actions, then ContextMenuBehaviour.Hide.
            &Act::Menu(i) => {
                let mut hide = true;
                if let (Some(p), Some(b)) = (play.as_deref_mut(), ui.context_buttons.get(i).cloned()) {
                    hide = p.game.context_menu_click(&b.actions);
                }
                if hide {
                    hide_context(&mut ui);
                }
                ui.dirty = true;
            }
            // SettingsGeneratorBehaviour.ApplySetting: GameSettingsInitBehaviour.Sync and VideoSettingsInitBehaviour.Sync are `Settings::prefs`
            // and `window` reading the changed Settings; MixerControllerBehaviour.Sync is audio; UserPreferenceManager.Save is files.settings
            // UserPreferenceManager.Current is the one Preferences the game reads live: a change reaches the running game at
            // once (its ShowTutorial, which the simulation clears, read back first).
            Act::Set(i, v) => {
                if let Some(p) = play.as_deref_mut() {
                    let t = Settings::index("ShowTutorial");
                    settings.values[t] = p.game.prefs.ShowTutorial as i32 as f32;
                }
                settings.set(*i, *v);
                files.settings = true;
                if let Some(p) = play.as_deref_mut() {
                    p.game.prefs = settings.prefs();
                }
            }
            Act::Rebind(i) => {
                // TriggerEditorBehaviour.StartWaiting: nothing while one is being edited (IsBeingEdited).
                if ui.rebinding.is_none() {
                    ui.rebinding = Some(*i);
                    uifn("TriggerEditorBehaviour.set_IsBeingEdited", || "True".into());
                }
                ui.dirty = true;
            }
            // TriggerEditorBehaviour.Unbind: Key and SecondaryKey None, SaveStateChanges, InputSystem.Save, SetText.
            Act::Unbind(i) => {
                controls.set(*i, "None", "None");
                let state = format!("{} {}", controls.binds[*i].0, controls.binds[*i].1);
                uifn("TriggerEditorBehaviour.Unbind", || state);
                files.controls = true;
                ui.dirty = true;
            }
            _ => {}
        }
        let effect = ui.press(&act, now);
        if matches!(act, Act::Slowmo) {
            ui.timeScaleTarget = if ui.slowmo { settings.get("SlowMotionSpeed") / 100.0 } else { 1.0 };
        }
        // Leaving a game: Global.OnDestroy.
        if play.is_some() && effect != Effect::None {
            global_on_destroy();
        }
        // Leaving a game: the tutorial flag the simulation clears is a preference.
        if let (Some(p), true) = (&play, effect != Effect::None) {
            let (i, v) = (Settings::index("ShowTutorial"), p.game.prefs.ShowTutorial as i32 as f32);
            if settings.values[i] != v {
                settings.values[i] = v;
                files.settings = true;
            }
        }
        match effect {
            Effect::Quit => {
                exit.write(AppExit::Success);
            }
            Effect::ToMenu => {
                // CatalogBehaviour.OnDestroy: SpawnedGameObjects.Clear().
                if play.is_some() {
                    uifn("CatalogBehaviour.OnDestroy", || "0".into());
                }
                for e in &sprites {
                    commands.entity(e).despawn();
                }
                commands.remove_resource::<Play>();
                commands.insert_resource(LogoFlashState::default());
                // The Menu scene loads: its UISoundBehaviour.Start.
                if let Some(m) = &art.menu_audio {
                    commands.insert_resource(m.clone());
                }
            }
            Effect::Load(_) | Effect::None => {}
        }
    }
}

/// Loads the map on the second frame of the "Loading" page.
fn loading(
    mut ui: ResMut<Ui>,
    controls: Res<Controls>,
    settings: Res<Settings>,
    mut commands: Commands,
    mut frames: Local<u8>,
    mut job: Local<Option<play::LoadJob>>,
    sprites: Query<Entity, With<play::MainScene>>,
    mut camera: Single<(&mut Transform, &mut Projection), With<crate::lights::MainCamera>>,
) {
    if ui.mode != Mode::Loading {
        (*frames, *job) = (0, None);
        return;
    }
    // The page is drawn before the load starts.
    if *frames < 3 {
        *frames += 1;
        ui.load_progress = 0.0;
        return;
    }
    let Some(map) = ui.map.clone() else { return };
    // SceneManager.LoadSceneAsync: one step a frame. SceneSwitchBehaviour.UpdateProgress passes task.progress each frame
    // until isDone (LoadJob::progress: objects read, up to 0.9), so the bar reads 90% at most before the scene switches.
    let result = play::guarded(|| {
        let j = job.get_or_insert_with(|| {
            // The player seeds UnityEngine.Random from the clock at startup, so each session differs; tests keep seed 0.
            let seed = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.as_nanos() as i32);
            play::LoadJob::new(&ui.game, &map, ui.item.as_deref(), Some(settings.prefs()), seed)
        });
        let Some(mut g) = j.advance()? else {
            return Ok(None);
        };
        g.control_binds = Some(controls.binds.clone());
        let catalog = match g.assets.as_deref_mut() {
            Some(db) => data::catalog(db)?,
            None => Default::default(),
        };
        Ok(Some((g, catalog)))
    });
    match result {
        Ok(None) => {
            let p = job.as_ref().map_or(0.0, |j| j.progress());
            if ui.load_progress != p {
                ui.load_progress = p;
                ui.dirty = true;
            }
        }
        Ok(Some((game, catalog))) => {
            (*frames, *job) = (0, None);
            for e in &sprites {
                commands.entity(e).despawn();
            }
            camera.0.translation = Vec3::ZERO;
            *camera.1 = crate::lights::start_projection();
            ui.catalog = catalog;
            ui.category = 0;
            // The old game goes first, so the new one is an added Play (its views start over: `is_added`).
            commands.remove_resource::<Play>();
            commands.insert_resource(Play::new(game));
            // CatalogBehaviour.OnDestroy: the old Main scene's catalog goes (SpawnedGameObjects.Clear()).
            if ui.loading_in_main {
                uifn("CatalogBehaviour.OnDestroy", || "0".into());
            }
            // The Main scene activates: the Menu scene's objects (its UI Sound Controller) are gone.
            commands.remove_resource::<MenuAudio>();
            ui.started();
        }
        Err(e) => {
            (*frames, *job) = (0, None);
            ui.failed(e)
        }
    }
}

/// CatalogBehaviour.CreateItemButtons after a save or a delete (`catalog_dirty`): the contraption buttons are made again, each with its thumbnail
/// (ContraptionSpriteStorage.GetFor, whose cache the game never empties).
fn contraption_buttons(
    mut ui: ResMut<Ui>,
    mut play: Option<ResMut<Play>>,
    mut art: ResMut<art::UiArt>,
    mut images: ResMut<Assets<Image>>,
    mut storage: Local<crate::game::contraption::ContraptionSpriteStorage>,
) {
    let Some(play) = play.as_deref_mut() else { return };
    let dirty = std::mem::take(&mut play.game.contraption.catalog_dirty);
    if dirty {
        // ContraptionSpriteStorage is never cleared by the game: a name saved again keeps its first picture, a failed picture stays null.
        ui.catalog.create_contraption_buttons();
        ui.dirty = true;
    }
    let missing: Vec<_> = ui.catalog.items.iter().filter_map(|i| i.local.as_ref()).filter(|m| !art.items.contains_key(&format!("local:{}", m.name())) && !storage.HasFor(m)).cloned().collect();
    if !missing.is_empty() {
        for m in missing {
            if let Some(a) = art::thumbnail_art(&mut images, &mut storage, &m) {
                art.items.insert(format!("local:{}", m.name()), a);
            }
        }
        ui.dirty = true;
    }
}

/// SpawnableOutlineBehaviour's active children: the transform's state; play::spawnable_outline_sprites draws the children.
fn spawnable_outline(ui: Res<Ui>, play: Option<ResMut<Play>>) {
    let Some(mut play) = play else { return };
    // CatalogBehaviour.ShowContraptionOutline / HideContraptionOutline / Update: SetOutline, the flip, the active flag and the mouse position.
    let g = &mut play.game;
    match &ui.local.outline {
        Some((rects, flip)) => {
            if !g.spawnable_outline.active || g.spawnable_outline.flip != *flip {
                g.spawnable_outline.SetOutline(rects);
            }
            g.spawnable_outline.active = true;
            g.spawnable_outline.flip = *flip;
            g.spawnable_outline.position = [g.MousePosition[0], g.MousePosition[1]];
        }
        None => g.spawnable_outline.active = false,
    }
}

/// A game that started with the app (--play-map) lists its catalog once.
fn late_catalog(mut ui: ResMut<Ui>, mut play: Option<ResMut<Play>>, mut tried: Local<bool>) {
    let Some(play) = play.as_deref_mut() else {
        *tried = false;
        return;
    };
    if *tried || ui.mode != Mode::Game || !ui.catalog.categories.is_empty() {
        return;
    }
    *tried = true;
    match play.game.assets.as_deref_mut().map(data::catalog) {
        Some(Ok(c)) => ui.catalog = c,
        Some(Err(e)) => ui.error = Some(e),
        None => {}
    }
    // The hidden capture can open the Local category (PPG_PAGE=local).
    if std::env::var("PPG_PAGE").is_ok_and(|p| p == "local") {
        ui.category = ui.catalog.categories.iter().position(|c| c.name == "Local").unwrap_or(ui.category);
    }
    // Or any category by name, its list scrolled to an item (PPG_CATEGORY=Firearms[,Portal Gun]).
    if let Ok(v) = std::env::var("PPG_CATEGORY") {
        let (name, item) = v.split_once(',').unwrap_or((&v, ""));
        ui.category = ui.catalog.categories.iter().position(|c| c.name == name).unwrap_or(ui.category);
        let row = ui.catalog.items.iter().filter(|i| i.category == ui.category).position(|i| i.name == item).map_or(0, |k| k / 3);
        ui.scroll.insert(3, row.saturating_sub(2) as f32 * 72.0);
    }
    ui.dirty = true;
}

// ---------------------------------------------------------------- the view

fn rebuild(
    mut commands: Commands,
    mut ui: ResMut<Ui>,
    settings: Res<Settings>,
    controls: Res<Controls>,
    play: Option<Res<Play>>,
    roots: Query<Entity, With<Root>>,
    art: Res<art::UiArt>,
    mut shown_stopped: Local<bool>,
    buttons: Query<(&Press, &Hovered, Option<&view::Tint>)>,
    mut carried: ResMut<Carried>,
) {
    let stopped = play.as_ref().and_then(|p| p.stopped.as_deref());
    if stopped.is_some() != *shown_stopped {
        *shown_stopped = stopped.is_some();
        ui.dirty = true;
    }
    if !ui.dirty {
        return;
    }
    ui.dirty = false;
    carried.0 = buttons.iter().map(|(p, h, t)| (p.0.clone(), h.get(), t.copied())).collect();
    for e in &roots {
        commands.entity(e).despawn();
    }
    build(&mut commands, &ui, &settings, &controls, &art, stopped);
}

/// The rebuilt buttons take the hover and tint tween of the old ones with the same Act, so a rebuild neither drops
/// the hover (tooltip, highlight) for a frame nor restarts a fade.
fn carry_over(mut carried: ResMut<Carried>, mut fresh: Query<(Entity, &Press, Option<&mut view::Tint>), Added<Press>>, mut commands: Commands) {
    if carried.0.is_empty() {
        return;
    }
    for (e, press, tint) in &mut fresh {
        let Some((_, hovered, old)) = carried.0.iter().find(|(a, ..)| *a == press.0) else { continue };
        if *hovered {
            commands.entity(e).insert(Hovered(true));
        }
        if let (Some(mut t), Some(o)) = (tint, old) {
            (t.down, t.cur, t.from, t.to, t.elapsed) = (o.down, o.cur, o.from, o.to, o.elapsed);
        }
    }
    carried.0.clear();
}

/// ToolControllerBehaviour.UpdateSelectionBox (run by its Update, so not while paused): while isSelecting and the drag
/// from selectionDragStart is past sqrt(200) pixels, Show and place the box between the two points (canvas units:
/// pixels over the CanvasScaler's scale) with SetSizeDisplay of the world drag times 0.82397; nearer, Hide. Outside a
/// drag it keeps what it showed; StopSelectionDrag hides it.
fn selection_box(
    ui: Res<Ui>,
    scale: Res<UiScale>,
    play: Option<Res<Play>>,
    window: Single<&Window, With<PrimaryWindow>>,
    mut boxes: Query<&mut Node, With<SelBox>>,
    mut texts: Query<(&SelBoxText, &mut Text)>,
    mut was_selecting: Local<bool>,
) {
    let Some(play) = play else { return };
    let g = &play.game;
    let Ok(mut node) = boxes.single_mut() else { return };
    let (Some(t), Some(screen)) = (g.tool.as_ref(), g.input.screen) else { return };
    if !t.isSelecting {
        if std::mem::take(&mut *was_selecting) && node.display != Display::None {
            node.display = Display::None;
        }
        return;
    }
    *was_selecting = true;
    // Update's guard: no pause menu, no dialog box, no UI block.
    if ui.mode != Mode::Game || ui.colour.is_some() || g.input.ui_block {
        return;
    }
    let (start, mouse) = (t.selectionDragStart, screen.mouse);
    let d = [mouse[0] - start[0], mouse[1] - start[1]];
    if d[0] * d[0] + d[1] * d[1] <= 200.0 {
        node.display = Display::None;
        return;
    }
    let k = scale.0;
    let (x, w) = if d[0] < 0.0 { (mouse[0], (mouse[0] - start[0]).abs()) } else { (start[0], d[0].abs()) };
    let (y, h) = if d[1] > 0.0 { (mouse[1], (mouse[1] - start[1]).abs()) } else { (start[1], d[1].abs()) };
    node.display = Display::Flex;
    node.left = px(x / k);
    node.top = px((window.height() - y) / k);
    node.width = px(w / k);
    node.height = px(h / k);
    let from = screen.to_world(start);
    let snap = crate::game::tool_wheel::selection_box_snap;
    let size = [(g.MousePosition[0] - from[0]) * 0.82397, (g.MousePosition[1] - from[1]) * 0.82397];
    for (which, mut text) in &mut texts {
        let s = format!("{}m", snap(if which.0 { size[0] } else { size[1] }));
        if text.0 != s {
            text.0 = s;
        }
    }
}

/// NotificationAnimationBehaviour.Awake: the text it moves is `NoteText`. NotificationAnimationBehaviour.OffsetCurve (Notification.prefab): time, value, inSlope, outSlope; clamped both ends.
pub(super) fn note_offset_curve() -> crate::game_assets::Curve {
    crate::game_assets::Curve {
        keys: vec![[0.0, 0.0068359375, 0.044340834, 0.044340834], [0.03, 0.0, 0.0, 0.0], [0.94453645, 0.009758674, 0.01845219, 0.01845219], [1.0, 1.0, 44.395573, 44.395573]],
        pre: 2,
        post: 2,
    }
}

/// NotificationAnimationBehaviour.Update: the text's x, (renderedWidth + 100) * OffsetCurve(t / GetNotificationLifetime()).
pub(super) fn note_offset(c: &crate::game_assets::Curve, cache: &mut crate::game_assets::CurveCache, t: f64, width: f32) -> f32 {
    (width + 100.0) * c.evaluate(cache, (t / 15.0) as f32)
}

/// NotificationControllerBehaviour.DestroyNotification: a notification leaves the list and the screen (the area's children follow
/// Ui.notes) NotificationLifetime (15 in the Main scene) real seconds after CreateNotification made it.
/// NotificationAnimationBehaviour.Update's t (unscaled) over the lifetime through OffsetCurve moves the text right by
/// (renderedWidth + 100) times it.
fn notes_update(
    mut commands: Commands,
    time: Res<Time<Real>>,
    mut ui: ResMut<Ui>,
    areas: Query<Entity, With<NoteArea>>,
    notes: Query<(Entity, &Note)>,
    mut texts: Query<(&mut Node, &Children, &ChildOf), With<NoteText>>,
    words: Query<&ComputedNode, Without<NoteText>>,
    parents: Query<&ChildOf, Without<NoteText>>,
    mut curve: Local<Option<(crate::game_assets::Curve, crate::game_assets::CurveCache)>>,
) {
    // NotificationControllerBehaviour.GetNotificationLifetime: NotificationLifetime, the Main scene's 15
    const LIFETIME: f64 = 15.0;
    // NotificationAnimationBehaviour.Update: t over the lifetime through OffsetCurve moves the text (the loop over `texts` below)
    let now = time.elapsed_secs_f64();
    if ui.notes.iter().any(|(_, born)| now - born >= LIFETIME) {
        ui.notes.retain(|(_, born)| now - born < LIFETIME);
    }
    let Ok(area) = areas.single() else { return };
    for (e, n) in &notes {
        if !ui.notes.iter().any(|(_, born)| *born == n.0) {
            commands.entity(e).despawn();
        }
    }
    for (text, born) in &ui.notes {
        if !notes.iter().any(|(_, n)| n.0 == *born) {
            commands.entity(area).with_children(|a| view::note(a, text, *born));
        }
    }
    let (c, cache) = curve.get_or_insert_with(|| (note_offset_curve(), Default::default()));
    for (mut node, children, child_of) in &mut texts {
        let Ok(holder) = parents.get(child_of.parent()) else { continue };
        let Ok((_, n)) = notes.get(holder.parent()) else { continue };
        let width: f32 = children.iter().filter_map(|w| words.get(w).ok()).map(|w| w.size().x * w.inverse_scale_factor()).sum();
        let t = now - n.0;
        let offset = note_offset(c, cache, t, width);
        uifn("NotificationControllerBehaviour.GetNotificationLifetime", || LIFETIME.to_string());
        uifn("NotificationAnimationBehaviour.Update", || format!("{t} {width} {offset}"));
        let left = px(offset);
        if node.left != left {
            node.left = left;
        }
    }
}

/// Selectable.DoStateTransition with ColorTint: pressed while the press that began on it is held over it, highlighted
/// while hovered, else normal; the tint moves to its target over fadeDuration.
fn tints(
    time: Res<Time<Real>>,
    mouse: Res<ButtonInput<MouseButton>>,
    selection: Res<Selection>,
    mut q: Query<(&mut view::Tint, &Hovered, &mut BackgroundColor, Option<&Press>, Option<&Children>, Has<view::TintPicture>)>,
    mut pictures: Query<&mut ImageNode>,
) {
    let dt = time.delta_secs();
    for (mut t, hovered, mut bg, press, children, picture) in &mut q {
        // A new button (or one `carry_over` gave an old one's tween) is drawn at its tint now.
        let fresh = t.is_changed();
        let over = hovered.get();
        if mouse.just_pressed(MouseButton::Left) && over {
            t.down = true;
        }
        if !mouse.pressed(MouseButton::Left) {
            t.down = false;
        }
        // Selectable.currentSelectionState: Pressed, then Selected (for the buttons whose Selected colour is read), then Highlighted.
        let selected = t.selected.filter(|_| press.is_some_and(|p| selection.0.as_ref() == Some(&p.0)));
        let target = if t.down && over { t.pressed } else if let Some(c) = selected { c } else if over { t.high } else { t.normal };
        if target != t.to {
            (t.from, t.to, t.elapsed) = (t.cur, target, 0.0);
        }
        if t.cur != t.to {
            t.elapsed += dt;
            let k = if t.fade > 0.0 { (t.elapsed / t.fade).min(1.0) } else { 1.0 };
            let (from, to) = (t.from, t.to);
            t.cur = std::array::from_fn(|i| from[i] + (to[i] - from[i]) * k);
        } else if !fresh {
            continue;
        }
        let c = t.color();
        if picture {
            for &child in children.into_iter().flatten() {
                if let Ok(mut image) = pictures.get_mut(child) {
                    image.color = c;
                }
            }
        } else {
            bg.0 = c;
        }
    }
}

/// Texts, colours and slider fills that follow the state without a rebuild.
fn live(
    time: Res<Time<Real>>,
    ui: Res<Ui>,
    settings: Res<Settings>,
    controls: Res<Controls>,
    play: Option<Res<Play>>,
    (mut fps, mut last_tip): (ResMut<Fps>, Local<String>),
    (tips, env_tips): (Query<(&Tip, &Hovered)>, Query<(&view::EnvTip, &Hovered)>),
    mut texts: Query<(&Bound, &mut Text)>,
    mut looks: Query<(&Look, &Hovered, &mut BackgroundColor)>,
    mut fills: Query<(&FillOf, &mut Node), Without<Flyout>>,
    mut boxes: Query<(&TipBox, &mut Visibility)>,
    mut flyouts: Query<(&ChildOf, &mut Node, &Flyout)>,
    mut flyout_state: ResMut<view::Flyouts>,
    hovers: Query<&Hovered>,
    mut checks: Query<(&Checked, &mut TextColor)>,
    mut status_items: Query<(&view::StatusItem, &mut Node), (Without<FillOf>, Without<Flyout>)>,
) {
    let now = time.elapsed_secs_f64();
    // FramerateViewBehaviour.Update
    fps.frames += 1;
    fps.time += time.delta_secs();
    if fps.time > 1.0 {
        fps.shown = Some(fps.frames);
        (fps.frames, fps.time) = (0, 0.0);
    }
    // HasTooltipBehaviour.OnPointerEnter: the hovered button's text shows in its tooltip box (the text already went through
    // AppendPunctuation: state::tooltip).
    // HasTooltipBehaviour.OnPointerExit: the box hides again once nothing with a tip is hovered.
    let tip = |tool: bool| tips.iter().filter(|(t, h)| h.get() && t.1 == tool).map(|(t, _)| t.0.as_str()).find(|t| !t.is_empty()).unwrap_or("");
    let scale = play.as_ref().map_or(1.0, |p| p.game.time.timeScale);
    // StatusController.Update: TimeScaleView while |timeScale - 1| > 0.02, FramerateView while ShowFramerate.
    for (item, mut node) in &mut status_items {
        let on = match item {
            view::StatusItem::TimeScale => (scale - 1.0).abs() > 0.02,
            view::StatusItem::Framerate => settings.flag("ShowFramerate"),
        };
        let display = if on { Display::Flex } else { Display::None };
        if node.display != display {
            node.display = display;
        }
    }
    // StatusController.Update (Main scene): TimeScaleView, LimbStatusView, InvisibleTool, FramerateView, ThermalVisionView.
    if play.is_some() {
        let state = [(scale - 1.0).abs() > 0.02, ui.detail, ui.tools_invisible, settings.flag("ShowFramerate"), ui.thermal].map(cs).join(" ");
        uifn("StatusController.Update", || state);
    }
    // HasTooltipBehaviour.OnPointerEnter / OnPointerExit: the tip box shown with its text, or hidden.
    let shown_tip = [tip(false), tip(true)].into_iter().find(|t| !t.is_empty()).map(str::to_string).or_else(|| env_tips.iter().find(|(_, h)| h.get()).map(|(t, _)| append_punctuation(&t.0))).unwrap_or_default();
    if shown_tip != *last_tip {
        if shown_tip.is_empty() {
            uifn("HasTooltipBehaviour.OnPointerExit", || "False".into());
        } else {
            let state = format!("True {}", ui_text(&shown_tip));
            uifn("HasTooltipBehaviour.OnPointerEnter", || state);
        }
        *last_tip = shown_tip;
    }
    for (bound, mut text) in &mut texts {
        let s = match bound {
            Bound::Setting(i) => settings.text(*i),
            // The Trigger text's TMP style is Bold | UpperCase.
            Bound::Bind(i) => if ui.rebinding == Some(*i) { crate::il!(str "KeyTriggerEditor/<WaitForUserInput>d__10::MoveNext" 0).to_uppercase() } else { controls.text(*i).to_uppercase() },
            // TimeScaleViewBehaviour.Update: Mathf.Round(Time.timeScale * 100) + "%".
            Bound::TimeScale => {
                let n = (scale * 100.0).round();
                // Its object is active (StatusController) while the scale is off 1.
                if (scale - 1.0).abs() > 0.02 {
                    uifn("TimeScaleViewBehaviour.Update", || format!("{n} %"));
                }
                format!("{n}%")
            }
            Bound::Framerate => fps.shown.map_or("000".into(), |n| n.to_string()),
            // "title\ndescription".
            Bound::Tip(tool, title) => {
                let (a, b) = tip(*tool).split_once('\n').unwrap_or((tip(*tool), ""));
                (if *title { a } else { b }).to_string()
            }
            // HasTooltipBehaviour.OnPointerEnter with the environment window's TooltipText: AppendPunctuation(Text); OnPointerExit hides it.
            Bound::EnvTip => env_tips.iter().find(|(_, h)| h.get()).map_or(String::new(), |(t, _)| append_punctuation(&t.0)),
            Bound::Filter => if ui.filter.is_empty() && !ui.typing { "filter".into() } else { format!("{}{}", ui.filter, if ui.typing { "_" } else { "" }) },
        };
        if text.0 != s {
            text.0 = s;
        }
    }
    for (look, hovered, mut bg) in &mut looks {
        let selected = look.sel.selected(&ui, &settings, &controls);
        let c = look.colour(selected, hovered.get(), &ui, &controls);
        if bg.0 != c {
            bg.0 = c;
        }
    }
    for (&FillOf(i), mut node) in &mut fills {
        node.width = percent(settings.fraction(i) * 100.0);
    }
    for (b, mut v) in &mut boxes {
        let shown = if tip(b.0).is_empty() { Visibility::Hidden } else { Visibility::Inherited };
        if *v != shown {
            *v = shown;
        }
    }
    // UiHoverEventEmitter.OnMouseEnter / OnMouseExit on a button with a child container: SetActive(true) / SetActive(false).
    for (parent, mut node, Flyout(name)) in &mut flyouts {
        let hovered = hovers.get(parent.parent()).is_ok_and(|h| h.get());
        let shown = if flyout_state.hover(name, hovered) { Display::Flex } else { Display::None };
        if node.display != shown {
            node.display = shown;
        }
    }
    for (c, mut color) in &mut checks {
        let want = if c.0.selected(&ui, &settings, &controls) { CHECKED } else { Color::WHITE };
        if color.0 != want && color.0.alpha() == 1.0 {
            color.0 = want;
        }
    }
}

/// Preferences and controls to disk, once the mouse is up.
fn save(mut files: ResMut<Files>, mut settings: ResMut<Settings>, controls: Res<Controls>, mouse: Res<ButtonInput<MouseButton>>, window: Single<&Window, With<PrimaryWindow>>) {
    if mouse.pressed(MouseButton::Left) {
        return;
    }
    if files.settings {
        files.settings = false;
        if let Err(e) = std::fs::write(files.settings_path(), settings.save_text((window.physical_width() as i32, window.physical_height() as i32))) {
            eprintln!("preferences not saved: {e}");
        }
    }
    if files.controls {
        files.controls = false;
        if let Err(e) = std::fs::write(files.controls_path(), controls.json()) {
            eprintln!("controls not saved: {e}");
        }
    }
}

/// VSync and Window mode.
fn window(mut settings: ResMut<Settings>, mut window: Single<&mut Window, With<PrimaryWindow>>, mut scale: ResMut<UiScale>, mut ui: ResMut<Ui>, mut last_resolution: Local<Option<[f32; 2]>>) {
    let screen = [window.physical_width() as f32, window.physical_height() as f32];
    if ui.screen != screen {
        ui.screen = screen;
        ui.dirty = true;
    }
    // LightRenderCameraBehaviour.Update: below. LightRenderCameraBehaviour (Main scene): Start's CreateNewRendertexture records lastResolution; Update, when the
    // main camera's pixel size differs, sets UserPreferenceManager.Current.Resolution to Screen.width x height (saved
    // with the next Save) and ResetRT (presentation: the light overlay's render texture).
    if matches!(ui.mode, Mode::Game | Mode::Pause) {
        match *last_resolution {
            None => *last_resolution = Some(screen),
            Some(last) if last != screen => {
                settings.bypass_change_detection().resolution = Some((screen[0] as i32, screen[1] as i32));
                *last_resolution = Some(screen);
            }
            Some(_) => {}
        }
    } else {
        *last_resolution = None;
    }
    // CanvasScaler: scale with screen, 2688 wide, matching the width.
    let fit = window.width() / view::CANVAS_WIDTH;
    if scale.0 != fit {
        scale.0 = fit;
    }
    if !settings.is_changed() {
        return;
    }
    let present = if settings.flag("VSync") { PresentMode::AutoVsync } else { PresentMode::AutoNoVsync };
    if window.present_mode != present {
        window.present_mode = present;
    }
    let mode = match settings.get("WindowMode") as i32 {
        0 => WindowMode::Windowed,
        1 => WindowMode::BorderlessFullscreen(MonitorSelection::Current),
        _ => WindowMode::Fullscreen(MonitorSelection::Current, VideoModeSelection::Current),
    };
    if window.mode != mode {
        window.mode = mode;
    }
}

// ---------------------------------------------------------------- the game under it

/// CameraControlBehaviour.LateUpdate ran in the frame: Global.CameraPosition and orthographicSize onto this window's camera.
fn camera(play: Res<Play>, mut camera: Single<(&mut Transform, &mut Projection), With<crate::lights::MainCamera>>) {
    let g = &play.game;
    let (transform, projection) = &mut *camera;
    let Projection::Orthographic(o) = &mut **projection else { return };
    let (p, q) = g.camera_world();
    transform.translation.x = p[0];
    transform.translation.y = p[1];
    transform.rotation = Quat::from_xyzw(q[0], q[1], q[2], q[3]);
    o.scale = g.camera.orthographic_size;
    // PPG_VIEW=<x>,<y>,<size> (the rendering check, with PPG_SHOT): the camera looks there instead.
    if std::env::var("PPG_VIEW").is_ok_and(|v| v == "fit") {
        let b = &g.BoundingBox;
        (transform.translation.x, transform.translation.y, o.scale) = (b.center[0], b.center[1], b.extents[1].max(b.extents[0] / 1.6) * 1.05);
    } else if let Some(v) = std::env::var("PPG_VIEW").ok().map(|v| v.split(',').filter_map(|x| x.parse::<f32>().ok()).collect::<Vec<_>>()).filter(|v| v.len() == 3) {
        (transform.translation.x, transform.translation.y, o.scale) = (v[0], v[1], v[2]);
    }
}

/// One frame of the game, under Global's time scale: paused or slowed by the toolbar, 0 in the pause menu.
// SteamWarningDialog.Update (Menu scene), below.
/// SteamWarningDialog.Update (Menu scene: Delay 5, Height 420): Start resets t (the scene loads), Update adds Time.unscaledDeltaTime and, past the
/// delay, shows the Notification when SteamworksInitialiser.IsInitialised is false (it never is: Steamworks is not linked), once per run
/// (alreadyShown), then disables itself.
/// Rewrite feature: local achievements (no Steam). An unlock shows as a notification instead of Steam's overlay toast.
fn achievement_toasts(time: Res<Time<Real>>, mut ui: ResMut<Ui>) {
    let toasts = std::mem::take(&mut crate::achievements::store().toasts);
    for title in toasts {
        ui.notify(format!("Achievement unlocked: {title}"), time.elapsed_secs_f64());
    }
}

/// The Menu scene's DiskLogger: Awake when the Menu scene loads (the menu shows), OnDestroy when it unloads (a map loads).
fn menu_disk_logger(ui: Res<Ui>, mut logger: Local<Option<crate::game::disk_logger::DiskLogger>>) {
    let menu = matches!(ui.mode, Mode::Menu | Mode::Loading);
    if menu && logger.is_none() {
        *logger = Some(crate::game::disk_logger::DiskLogger::awake(&crate::game::disk_logger::user_data_dir(), "Menu"));
    } else if !menu && logger.is_some() {
        *logger = None;
    }
}

fn steam_warning(time: Res<Time<Real>>, mut ui: ResMut<Ui>) {
    if ui.mode != Mode::Menu {
        ui.steam_t = Some(0.0).filter(|_| !ui.steam_shown);
        return;
    }
    // Rewrite feature: no Steam (the owner's choice; stats and achievements are local), so the rewrite counts as
    // "initialised" and the warning never shows. The dialog below stays for a future Steam mode.
    const STEAM_OFF_BY_CHOICE: bool = true;
    if STEAM_OFF_BY_CHOICE {
        return;
    }
    let Some(t) = ui.steam_t else { return };
    let t = t + time.delta_secs();
    if t <= 5.0 {
        ui.steam_t = Some(t);
        return;
    }
    // SteamWarningDialog.Start: t = 0 and disabled when alreadyShown (the reset above). SteamWarningDialog..ctor: Delay, Width, Height, Title, Message from the Menu scene.
    // DialogBoxManager.Notification: the text as the title and one OK button that closes; DialogBox.SetHeight(Height.Value) since Height.Active; Width is not active.
    // UISoundBehaviour.Main.Warning() is audio.
    let mut dialog = state::DialogView::notification("<b>Steam is not initialised</b>

The game failed to detect Steam. Some features may not work correctly.

Try restarting the game or the Steam client.");
    dialog.set_height(420.0);
    ui.open_dialog(dialog);
    ui.steam_shown = true;
    ui.steam_t = None;
    ui.dirty = true;
}

fn game_frame(time: Res<Time<Real>>, mut ui: ResMut<Ui>, mut play: ResMut<Play>, mut settings: ResMut<Settings>, mut files: ResMut<Files>) {
    if ui.mode == Mode::Loading || play.stopped.is_some() {
        return;
    }
    let real = time.delta_secs();
    // Global.set_Paused: ModdingApi.Events.OnChangePause fires when the toolbar flips Paused.
    if play.game.paused != ui.paused {
        play.game.set_paused(ui.paused);
    }
    // Global.SlowMotion and timeScaleTarget: the UI's toolbar toggles them (Act::Slowmo); Global.Update eases to the target.
    play.game.SlowMotion = ui.slowmo;
    play.game.timeScaleTarget.0 = ui.timeScaleTarget;
    // Time.timeScale is stepped from the unscaled delta once the frame is done, so it applies from the next one.
    // At a zero scale Time.deltaTime is 0: no fixed step runs, the Update scripts still do.
    if ui.mode == Mode::Game {
        if let Err(m) = play::step(&mut play.game, real) {
            play.stopped = Some(m);
            return;
        }
    }
    // PP_SELBOX=<start x>,<start y>,<mouse x>,<mouse y> (screen pixels, y up; the hidden capture of the selection box):
    // a drag held between the two points after the frame.
    if let Ok(v) = std::env::var("PP_SELBOX") {
        let f: Vec<f32> = v.split(',').map(|s| s.parse().expect("PP_SELBOX")).collect();
        let g = &mut play.game;
        if let (Some(t), Some(s)) = (g.tool.as_mut(), g.input.screen.as_mut()) {
            (t.isSelecting, t.selectionDragStart, s.mouse) = (true, [f[0], f[1]], [f[2], f[3]]);
            let w = s.to_world(s.mouse);
            g.MousePosition = [w[0], w[1], 0.0];
        }
    }
    // NotificationControllerBehaviour.Show
    for n in std::mem::take(&mut play.game.notifications) {
        ui.notify(n, time.elapsed_secs_f64());
    }
    // DialogBoxManager.Dialog / Notification from the Game (contraption.rs): one open at a time, the rest wait.
    if ui.dialog.is_none() && !play.game.contraption.dialogs.is_empty() {
        let r = play.game.contraption.dialogs.remove(0);
        ui.dialog = Some(state::DialogView {
            title: r.title,
            width: None,
            height: r.height,
            buttons: r.buttons.into_iter().map(|(t, c, a)| (t, c, a.map(state::DialogRun::Game))).collect(),
            entered: None,
        });
        ui.dirty = true;
    }
    // The pause menu holds the frame and the game does not step, but Global.Update still runs (its keys, the timeScale easing).
    if ui.mode != Mode::Game {
        play.game.time.unscaledDeltaTime = real;
        play.game.global_update();
    }
    global_read_back(&mut ui, &mut play.game, &mut settings, &mut files, time.elapsed_secs_f64());
}

/// What Global.Update changed, back into the UI: the pause menu and its page, Paused, SlowMotion and its target, the
/// preferences it saves (UserPreferenceManager.Save is files.settings), the item eyedrop chose and a context menu it hid.
fn global_read_back(ui: &mut Ui, g: &mut crate::game::Game, settings: &mut Settings, files: &mut Files, now: f64) {
    if g.paused_menu != (ui.mode == Mode::Pause) {
        if g.paused_menu {
            ui.mode = Mode::Pause;
            ui.pages = vec![Page::Main];
            ui.stat_views_enable("Main");
            if let Some(p) = screens::page(&g.menu_page).filter(|p| *p != Page::Main) {
                ui.pages.push(p);
            }
        } else {
            ui.mode = Mode::Game;
            ENV_REGEN.store(true, std::sync::atomic::Ordering::Relaxed);
        }
        ui.dirty = true;
    }
    (ui.paused, ui.slowmo, ui.timeScaleTarget) = (g.paused, g.SlowMotion, g.timeScaleTarget.0);
    for (name, v) in [("ShowOutlines", g.prefs.ShowOutlines as i32 as f32), ("GridSnap", g.prefs.GridSnap), ("AngleSnap", g.prefs.AngleSnap as f32)] {
        let i = Settings::index(name);
        if settings.values[i] != v {
            settings.values[i] = v;
            files.settings = true;
        }
    }
    // CatalogBehaviour.SetItem, then SetCategory when the item's category is one of the catalog's.
    if g.catalog_selected != ui.item {
        if let Some(name) = g.catalog_selected.clone() {
            ui.press(&Act::Item(name.clone()), now);
            if let Some(c) = ui.catalog.items.iter().find(|i| i.local.is_none() && i.name == name).map(|i| i.category) {
                ui.press(&Act::Category(c), now);
            }
            ui.dirty = true;
        }
    }
    if std::mem::take(&mut g.context_hidden) {
        hide_context(ui);
    }
}

/// The cursor and the control scheme as the game's Input: the mouse position through this window's camera, and the
/// controls the simulation reads, for presses that began where the world may take them.
fn world_input(
    buttons: Res<ButtonInput<MouseButton>>,
    keys: Res<ButtonInput<KeyCode>>,
    controls: Res<Controls>,
    mut ui: ResMut<Ui>,
    hover: Res<HoverMap>,
    nodes: Query<(), With<Node>>,
    window: Single<&Window, With<PrimaryWindow>>,
    camera: Single<(&Camera, &GlobalTransform), With<crate::lights::MainCamera>>,
    mut play: ResMut<Play>,
    mut owned: Local<std::collections::HashMap<&'static str, bool>>,
    time_real: Res<Time<Real>>,
    mut shot_spawned: Local<bool>,
    wheel: Res<AccumulatedMouseScroll>,
) {
    let (camera, at) = *camera;
    let size = window.size();
    let (Ok(origin), Ok(one)) = (camera.viewport_to_world_2d(at, Vec2::new(0.0, size.y)), camera.viewport_to_world_2d(at, Vec2::new(1.0, size.y))) else { return };
    let input = &mut play.game.input;
    if let (Ok(min), Ok(max)) = (camera.viewport_to_world_2d(at, Vec2::new(0.0, size.y)), camera.viewport_to_world_2d(at, Vec2::new(size.x, 0.0))) {
        input.view = Some((min.to_array(), max.to_array()));
    }
    if let Some(c) = window.cursor_position().or(std::env::var("PP_SELBOX").is_ok().then_some(Vec2::ZERO)) {
        // Unity's screen y runs up from the bottom.
        let pixel = [c.x, size.y - c.y];
        let screen = crate::game::tool::Screen { mouse: pixel, origin: origin.to_array(), scale: one.x - origin.x, view: None };
        let w = screen.to_world(pixel);
        input.mouse = [w[0], w[1], 0.0];
        input.screen = Some(screen);
    } else {
        // No pointer (headless): the camera's view still holds (Camera.WorldToScreenPoint), the pointer where it last was.
        let mouse = input.screen.map_or([0.0; 2], |s| s.mouse);
        input.screen = Some(crate::game::tool::Screen { mouse, origin: origin.to_array(), scale: one.x - origin.x, view: None });
    }
    // ContextMenuBehaviour.Show ran in the game's last Update: open it at the pointer.
    if ui.detail != play.game.ShowLimbStatus {
        ui.detail = play.game.ShowLimbStatus;
        ui.dirty = true;
    }
    // StatusController.Update: the Thermal vision and Invis.Tools items follow ThermalVisionEnabled and the tool visibility.
    // ToolWheelBehaviour.SetTab: the Tabs objects (Canvas/Toolbar/Tools, /Powers) active for CurrentTab, the toolbar's list.
    if let Some(t) = play.game.tool.as_ref() {
        if ui.powers != (t.tab == 1) {
            ui.powers = t.tab == 1;
            ui.dirty = true;
        }
    }
    let (thermal, invisible) = (play.game.thermal_vision == Some(true), play.game.tool.as_ref().is_some_and(|t| t.invisible));
    // StatusController.Update reads ToolWheelBehaviour.Instance.ToolVisibility every frame.
    uifn("ToolWheelBehaviour.get_ToolVisibility", || crate::game::tool_wheel::visibility(invisible).into());
    if (ui.thermal, ui.tools_invisible) != (thermal, invisible) {
        (ui.thermal, ui.tools_invisible) = (thermal, invisible);
        ui.dirty = true;
    }
    if ui.entry.is_some() != play.game.entry.is_some() {
        ui.entry = play.game.entry.clone();
        ui.entry_all = true;
        ui.dirty = true;
    }
    // LayerEditorController's Container, shown at its screen position.
    let layer = play.game.layer_editor.container_active.then(|| {
        let p = play.game.layer_editor.container_position;
        ([if p[0].is_finite() { p[0] } else { 0.0 }, if p[1].is_finite() { p[1] } else { 0.0 }], play.game.layer_editor.LayerDisplay.clone(), play.game.layer_editor.OrderDisplay.clone())
    });
    if ui.layer != layer {
        ui.layer = layer;
        ui.dirty = true;
    }
    if ui.env_values != play.game.map_settings {
        ui.env_values = play.game.map_settings;
        ui.dirty = true;
    }
    if ui.colour.is_some() != play.game.colour.is_some() {
        ui.colour = play.game.colour.clone();
        ui.dirty = true;
    }
    if let Some(b) = play.game.context_menu.take() {
        // ContextMenuBehaviour.Show: ClampToScreen(screenPosition) (Unity's screen y runs up).
        match window.cursor_position() {
            Some(c) => show_context(&mut ui, c.to_array(), window.size().to_array(), b),
            None => hide_context(&mut ui),
        }
    }
    let inputs = Inputs { keys: &keys, mouse: &buttons };
    // Global.get_UILock's pointer-over-UI half (Game::ui_lock adds ResizeHandles.IsHovering)
    let over = over_ui(&hover, &nodes);
    // DialogBox.get_OpenDialogboxCount: the number of open boxes (the entry, colour, key and piano boxes)
    // DialogBox.set_OpenDialogboxCount: Start and Open add one, OnDestroy and Close take one
    // DialogBox.get_IsAnyDialogboxOpen: any of them open, which is what `now` tests
    // DialogBox.Close: a button with ClosesDialogBox ends its box (EntryApply, EntryCancel, ColourApply, ColourCancel, KeyApply, KeyCancel, PianoApply, PianoCancel)
    // DialogBox.OnDestroy: OpenDialogboxCount-- when the box is gone (the box's Option is None again)
    // DialogBox.get_InputKey: KeyBox::key, the key the key entry box sets (KeyTriggerBehaviour)
    // DialogBoxManager.Awake: Main = this; the boxes are `ui.entry`, `ui.colour`, `game.key_boxes` and `game.piano`
    let any_box = ui.is_any_dialogbox_open();
    let now = ui.mode == Mode::Game && !ui.typing && ui.rebinding.is_none() && !any_box && play.game.key_boxes.is_empty() && play.game.piano.is_none();
    let start = now && ui.context.is_none();
    // ToolControllerBehaviour.ToolChanged: the wheel highlights the tool the game chose (a tool key may have).
    if let Some(t) = play.game.tool.as_ref().filter(|t| !t.chosen.is_empty() && t.chosen != ui.tool) {
        ui.tool = t.chosen.clone();
        ui.dirty = true;
    }
    // Global.GetPausedMenu; MenuController.main.CurrentPage.
    play.game.paused_menu = ui.mode == Mode::Pause;
    play.game.menu_page = ui.pages.last().map_or("Main", |p| screens::page_name(*p)).into();
    let paused_menu = play.game.paused_menu;
    uifn("Global.GetPausedMenu", || cs(paused_menu).into());
    play.game.input.ui_hidden = ui.hide_ui;
    // The controls the simulation reads (ToolControllerBehaviour, DragTool, PinTool, ToolWheelBehaviour, ThermalVisionBehaviour); activateIndirect has no reader.
    for id in ["drag", "context", "fast", "snap", "left", "right", "activateDirect", "spawnLeft", "spawnRight", "delete", "undo", "copy", "paste", "flip", "snapToCenter", "toolInvisibility", "toggleThermalVision", "tool1", "tool2", "tool3", "tool4", "tool5", "tool6", "tool7", "tool8", "tool9"] {
        // ToolControllerBehaviour.Update asks for "tool0".."tool10" behind InputSystem.Has; only tool1..tool9 are actions.
        let own = owned.entry(id).or_default();
        let from_mouse = matches!(keys::src(&controls.bind(id).0), Some(Src::Mouse(_)));
        let allowed = if *own { now } else { start && !(from_mouse && over) };
        let c = gate(own, eval(&controls, id, &inputs), allowed);
        play.game.input.controls.insert(id.into(), c);
    }
    // Global.Update (not while the pause menu, a dialog box or a UI block is up): freezeSelection, igniteSelection and resizeSelection
    // Show the context menu at the pointer, run the button and Hide it (UISoundBehaviour.Blip is audio); eyedrop picks the item
    // under the pointer in the catalog.
    // Global.Update's keys (game/global.rs runs them; game_frame reads back what they changed). A text box being typed in
    // holds them, as it holds the UI's own keys.
    let free = !ui.typing && ui.env_edit.is_none();
    for id in [crate::il!(str "Global::Update" 0), crate::il!(str "Global::Update" 8), crate::il!(str "Global::Update" 7), "toggleLimbStatus", "freezeSelection", "igniteSelection", "resizeSelection", crate::il!(str "Global::Update" 12), "toggleHoveringHighlights", "incrementGrid", "decrementGrid", "incrementAngleSnap", "decrementAngleSnap"] {
        let c = if free && !(id == crate::il!(str "Global::Update" 0) && ui.pause_taken) { eval(&controls, id, &inputs) } else { Default::default() };
        play.game.input.controls.insert(id.into(), c);
    }
    let f1 = free && keys.just_pressed(KeyCode::F1);
    play.game.input.keys.insert("F1".into(), crate::game::tool::Control { down: f1, held: f1, up: false });
    // ContextMenuBehaviour.Show(Input.mousePosition): ClampToScreen; Camera.main.ScreenToWorldPoint(transform.position).
    // (No ClampToScreen record here: the game clamps only in Show and while the menu is open.)
    let at = {
        let (c, s) = (window.cursor_position().unwrap_or_default().to_array(), size.to_array());
        let k = crate::game::Game::context_clamp_to_screen([c[0], s[1] - c[1]], s);
        [k[0], s[1] - k[1]]
    };
    play.game.context_at = match (play.game.input.screen, play.game.input.window) {
        (Some(s), Some(w)) => s.to_world([at[0], w.size[1] - at[1]]),
        _ => [0.0, 0.0],
    };
    // TriggerEditorBehaviour.IsBeingEdited; DialogBox.IsAnyDialogboxOpen.
    play.game.trigger_being_edited = ui.rebinding.is_some();
    play.game.dialog_open = any_box || !play.game.key_boxes.is_empty() || play.game.piano.is_some();
    // CameraControlBehaviour reads these through InputSystem with its own checks (no dialog, UI block or pause menu).
    // LayerEditorController.Update reads the arrange controls the same way (it checks the UI block itself).
    for id in ["pan", "panLeft", "panRight", "panUp", "panDown", "zoomIn", "zoomOut", "arrangeSelection", "arrangeDown", "arrangeUp", "arrangeFront", "arrangeBack"] {
        play.game.input.controls.insert(id.into(), eval(&controls, id, &inputs));
    }
    // Input.mouseScrollDelta.y: wheel notches (winit reports Windows' wheel as lines of 120 units).
    let scroll = match wheel.unit {
        MouseScrollUnit::Line => wheel.delta.y,
        MouseScrollUnit::Pixel => unimplemented!("mod-only: Input.mouseScrollDelta from a pixel scroll"),
    };
    play.game.input.window = Some(crate::game::camera_control::WindowInput { size: size.to_array(), focused: window.focused, scroll, ui_lock: over });
    // Legacy Input by KeyCode, for KeyTriggerBehaviour.
    play.game.input.ui_block = !now || play.game.global_active_ui_block();
    // FollowingViewBehaviour.Update
    play.game.following_view_update();
    let follow = play.game.following_view_active.then(|| play.game.following_view_text.clone());
    if ui.follow != follow {
        ui.follow = follow;
        ui.dirty = true;
    }
    if let Some(at) = ui.context {
        // ContextMenuBehaviour.Update: if (isOpen) ClampToScreen(transform.position).
        uifn("ContextMenuBehaviour.get_isOpen", || "True".into());
        let clamped = clamp_context(at, size.to_array());
        if clamped != at {
            ui.context = Some(clamped);
            ui.dirty = true;
        }
        // Its corner in Unity's screen pixels (y up) and localScale.
        uifn("ContextMenuBehaviour.Update", || format!("{},{} {}", clamped[0], size.y - clamped[1], view::CONTEXT_SCALE));
        // TextUpdaterBehaviour.Update: each dynamic button's text = StringFunction().
        let ui = &mut *ui;
        for b in ui.context_buttons.iter_mut() {
            let text = play.game.menu_label(b.getter);
            if b.label != text {
                b.label = text;
                ui.dirty = true;
            }
        }
        // ConditionalTextBehaviour.Update (Time.unscaledDeltaTime)
        play.game.conditional_text_update(time_real.delta_secs());
        let on: Vec<bool> = CONTEXT_MENU.iter().map(|&(_, c)| play.game.context_condition(c)).collect();
        if ui.context_enabled != on {
            ui.context_enabled = on;
            ui.dirty = true;
        }
        let labels: Vec<Option<&'static str>> = CONTEXT_MENU.iter().map(|&(n, _)| play.game.context_label(n)).collect();
        if ui.context_labels != labels {
            ui.context_labels = labels;
            ui.dirty = true;
        }
    }
    for &(_, name) in crate::game::keycode::KEYCODES {
        if let Some(s) = keys::src(name) {
            let c = crate::game::tool::Control { down: inputs.down(s), held: inputs.held(s), up: inputs.up(s) };
            play.game.input.keys.insert(name.into(), c);
        }
    }
    // The key entry boxes' KeyTriggerEditor coroutines.
    let g = &mut play.game;
    let mouse = g.input.screen.map(|s| s.mouse);
    for b in g.key_boxes.iter_mut() {
        b.step(&g.input.keys, mouse);
    }
    if ui.key_boxes != g.key_boxes {
        ui.key_boxes = g.key_boxes.clone();
        ui.dirty = true;
    }
    // DialogBox.Start / ColorpickerDialogBehaviour.Open (OpenDialogboxCount++) and DialogBox.OnDestroy /
    // ColorpickerDialogBehaviour.Close (OpenDialogboxCount--) for the entry, key and colour boxes. A closed box goes at
    // the frame's end, after any box its button opened has started, so its change is recorded a frame later.
    if let Some(destroy) = ui.box_closed.take() {
        let n = ui.open_dialogbox_count();
        uifn("DialogBox.set_OpenDialogboxCount", || n.to_string());
        if destroy {
            uifn("DialogBox.OnDestroy", || n.to_string());
        }
    }
    let boxes = (ui.entry.is_some(), ui.key_boxes.len(), ui.colour.is_some());
    let prev = std::mem::replace(&mut ui.boxes_prev, boxes);
    if boxes.0 > prev.0 || boxes.1 > prev.1 || boxes.2 > prev.2 {
        let n = ui.open_dialogbox_count();
        uifn("DialogBox.set_OpenDialogboxCount", || n.to_string());
    }
    if boxes.0 < prev.0 || boxes.1 < prev.1 {
        ui.box_closed = Some(true);
    } else if boxes.2 < prev.2 {
        ui.box_closed = Some(false);
    }
    if ui.piano != g.piano {
        ui.piano = g.piano.clone();
        ui.dirty = true;
    }
    let v = &g.limb_view;
    let shown = v.active.then(|| (v.stats.clone(), v.blood.clone(), v.bars));
    if ui.limb_view != shown {
        ui.limb_view = shown;
        ui.dirty = true;
    }
    if play.game.catalog_selected != ui.item {
        play.game.catalog_selected = ui.item.clone();
    }
    if std::mem::take(&mut ui.local.changed) {
        play.game.catalog_contraption = ui.local.selected.as_ref().map(|s| (s.clone(), ui.local.meta.as_ref().and_then(|m| m.DisplayName.clone()).unwrap_or_default()));
    }
    // CatalogBehaviour.Update's outline: the spawn keys' timer, with the catalog usable (no pause menu, dialog or UI block).
    if !ui.paused && ui.dialog.is_none() {
        let key = |id: &str| play.game.input.controls.get(id).map_or((false, false, false), |c| (c.down, c.held, c.up));
        let (right, left) = (key("spawnRight"), key("spawnLeft"));
        ui.catalog_update(right, left, time_real.delta_secs());
    }
    // The hidden capture (PPG_SHOT) places the selected item at the origin, as a click there would.
    if std::env::var("PPG_SHOT").is_ok() && time_real.elapsed_secs() > 1.0 && !*shot_spawned {
        *shot_spawned = true;
        play.game.input.mouse = [0.0, 1.5, 0.0];
        play.game.input.controls.insert("spawnRight".into(), crate::game::tool::Control { down: false, held: false, up: true });
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The menu's systems and widgets on a headless app: no window, no renderer.
    /// None without an install: the pages are laid out from its scenes.
    fn app() -> Option<App> {
        let game = crate::game_assets::find_game(None).ok()?;
        scene::load(&mut crate::assets::db::AssetDb::open(&game).unwrap()).unwrap();
        std::fs::create_dir_all(std::env::temp_dir().join(format!("ppr-ui-test-{}", std::process::id()))).unwrap();
        let mut app = App::new();
        app.add_plugins((MinimalPlugins, bevy::input::InputPlugin)).init_resource::<HoverMap>().init_resource::<UiScale>();
        app.world_mut().spawn((Window::default(), PrimaryWindow));
        let rows = ["Default", "Arena"].map(|n| MapRow { name: n.into(), description: String::new() });
        let mut ui = new_ui(None, Mode::Menu, None, None);
        ui.maps = rows.into();
        app.insert_resource(ui)
            .insert_resource(Settings::default())
            .insert_resource(Controls::default())
            .insert_resource(Files { dir: std::env::temp_dir().join(format!("ppr-ui-test-{}", std::process::id())), settings: false, controls: false });
        add(&mut app);
        Some(app)
    }

    fn count<T: Component>(app: &mut App) -> usize {
        app.world_mut().query::<&T>().iter(app.world()).count()
    }

    #[test]
    fn menu_pages_build_and_settings_apply() {
        let Some(mut app) = app() else { return };
        app.update();
        // The main menu: Play, Settings, Mods, Information, Quit, and the rewrite's achievements beside Information.
        assert_eq!(count::<Press>(&mut app), 6);
        app.world_mut().resource_mut::<Queue>().0.push(Act::Nav(Page::Settings));
        app.update();
        app.update();
        // General: five sliders; the tab column (6 categories + Controls + Back) and the radio buttons.
        assert_eq!(count::<SliderOf>(&mut app), 5);
        let i = Settings::index("GorelessMode");
        app.world_mut().resource_mut::<Queue>().0.push(Act::Tab(1));
        app.world_mut().resource_mut::<Queue>().0.push(Act::Set(i, 1.0));
        app.update();
        app.update();
        assert!(app.world().resource::<Settings>().flag("GorelessMode"));
        let saved = std::fs::read_to_string(std::env::temp_dir().join(format!("ppr-ui-test-{}", std::process::id())).join("ppr-preferences.json")).unwrap();
        assert!(saved.contains("\"GorelessMode\": true"), "saved once the mouse is up");
        assert_eq!(count::<SliderOf>(&mut app), 2, "Gore: fragility and crush sensitivity");
        app.world_mut().resource_mut::<Queue>().0.push(Act::Nav(Page::Controls));
        app.update();
        app.update();
        let visible = ACTIONS.iter().filter(|a| ACTION_CATEGORIES.contains(&a.category) && !a.invisible).count();
        assert_eq!(count::<Bound>(&mut app), visible, "a binding text per listed action");
        app.world_mut().resource_mut::<Queue>().0.push(Act::Nav(Page::Maps));
        app.update();
        app.update();
        let text = |app: &mut App| app.world_mut().query::<&Text>().iter(app.world()).map(|t| t.0.clone()).collect::<Vec<_>>();
        assert!(text(&mut app).contains(&crate::il!(str "PlayButtonMapNameBehaviour::Update" 1).to_string()));
        app.world_mut().resource_mut::<Queue>().0.push(Act::SelectMap(1));
        app.update();
        app.update();
        assert!(text(&mut app).contains(&"Enter Arena".to_string()));
        // The Mods page: no mods, Steam not initialised, the warning and the two tool buttons.
        app.world_mut().resource_mut::<Queue>().0.extend([Act::Back, Act::Nav(Page::Mods)]);
        app.update();
        app.update();
        let t = text(&mut app);
        for s in ["No mods found", "Steam is not initialised", "filter", "Enable all ", "Disable all", "Open documentation in browser", "No mod selected"] {
            assert!(t.iter().any(|x| x == s), "{s} on the Mods page");
        }
        assert!(t.iter().any(|x| x.starts_with("Modding your game may cause bugs")));
        std::fs::remove_dir_all(std::env::temp_dir().join(format!("ppr-ui-test-{}", std::process::id()))).ok();
    }

    /// A left click on a static context menu button (Delete) keeps the menu open until the release runs the button.
    #[test]
    fn static_context_button_click_runs_it() {
        let mut app = App::new();
        app.add_plugins(MinimalPlugins).init_resource::<ButtonInput<MouseButton>>();
        let mut ui = new_ui(None, Mode::Game, None, None);
        ui.context = Some([10.0, 10.0]);
        app.insert_resource(ui).init_resource::<Queue>().init_resource::<Selection>().init_resource::<view::Flyouts>().add_systems(Update, clicks);
        app.world_mut().spawn((Press(Act::MenuStatic(0)), Hovered(true)));
        app.world_mut().resource_mut::<ButtonInput<MouseButton>>().press(MouseButton::Left);
        app.update();
        assert!(!app.world().resource::<Queue>().0.contains(&Act::Escape), "the press is on the menu");
        let mut mouse = app.world_mut().resource_mut::<ButtonInput<MouseButton>>();
        mouse.clear();
        mouse.release(MouseButton::Left);
        app.update();
        assert!(app.world().resource::<Queue>().0.contains(&Act::MenuStatic(0)));
    }

    /// Plays a real map under the UI: load, frames, reset and back to the menu (cargo test -- --ignored).
    #[test]
    #[ignore]
    fn the_installed_game_loads_resets_and_leaves() {
        let game = crate::game_assets::find_game(None).unwrap();
        let cache = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("local-cache");
        let Some(mut app) = app() else { return };
        app.add_plugins(AssetPlugin { file_path: cache.to_string_lossy().into_owned(), ..default() })
            .init_asset::<Image>().init_asset::<crate::limb_material::Body>().init_asset::<crate::limb_material::LegacyBody>().init_asset::<crate::wires::BloodWire>()
            .init_resource::<bevy::gizmos::config::GizmoConfigStore>()
            .insert_resource(crate::game_assets::HumanRig::load(&cache, &game).unwrap());
        app.world_mut().resource_mut::<bevy::gizmos::config::GizmoConfigStore>().insert(default(), bevy::gizmos::config::DefaultGizmoConfigGroup);
        app.world_mut().resource_mut::<Ui>().game = game.clone();
        // The game's own config.json (a fresh install would play the tutorial, which is not rewritten).
        app.world_mut().resource_mut::<Settings>().load(&std::fs::read_to_string(game.join("config.json")).unwrap_or_default());
        let maps = data::maps(&game).unwrap();
        let default = maps.iter().position(|m| m.name == "Default").unwrap();
        app.world_mut().resource_mut::<Ui>().maps = maps.into_iter().map(|m| MapRow { name: m.name, description: m.description }).collect();
        let queue = |app: &mut App, a: Act| app.world_mut().resource_mut::<Queue>().0.push(a);
        queue(&mut app, Act::SelectMap(default));
        queue(&mut app, Act::Enter);
        for _ in 0..8 {
            app.update();
        }
        assert_eq!(app.world().resource::<Ui>().mode, Mode::Game, "{:?}", app.world().resource::<Ui>().error);
        let first = app.world().resource::<Play>().game.time.frameCount;
        for _ in 0..30 {
            app.update();
        }
        let play = app.world().resource::<Play>();
        assert!(play.game.time.frameCount > first && play.stopped.is_none(), "{:?}", play.stopped);
        let shown = app.world().resource::<Ui>().catalog.shown(0, "").len();
        assert!(shown > 0);
        assert_eq!(count::<play::LimbSprite>(&mut app), app.world().resource::<Play>().game.limbs.len());
        let limbs = count::<play::LimbSprite>(&mut app);
        // Reset: a new game with fresh sprites, none left over.
        queue(&mut app, Act::Escape);
        queue(&mut app, Act::Restart);
        for _ in 0..8 {
            app.update();
        }
        assert_eq!(app.world().resource::<Ui>().mode, Mode::Game);
        assert_eq!(count::<play::LimbSprite>(&mut app), limbs);
        // Back to the menu: the game and its sprites are gone.
        queue(&mut app, Act::Escape);
        queue(&mut app, Act::ToMenu);
        app.update();
        app.update();
        assert!(app.world().get_resource::<Play>().is_none());
        assert_eq!(count::<play::LimbSprite>(&mut app), 0);
        assert_eq!(app.world().resource::<Ui>().mode, Mode::Menu);
    }
}
